# ===== vm_sysparams.py =============================================
"""INSTALL.CFG — Stratagy system parameters (read, decode, serialise).

The ``set <name> <value>`` / ``#set …`` lines come back as **confirmed**
plaintext (voicemail-map §2.9). This module parses them into the three-column
grid the old window shows — *Parameter Names | Values | Parameter Descriptions*
— preserving order, ``#``-disabled rows (shown as an "enabled" toggle) and the
``#- …`` group headings, joins each to its ``Install.dhp`` help entry, decodes
the shutdown schedule, and flags the cleartext default password. It can also
serialise the grid back to a byte-identical file for the (P3, gated) write path;
nothing here writes to the card.
"""


import json
import re
from typing import Dict, List, Optional


_SET_RE = re.compile(r"^(#)?\s*set\s+(\w+)\s*(.*?)\s*$")
_GROUP_RE = re.compile(r"^#-\s*(.*?)\s*$")
_DAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday",
         "Saturday"]

_HELP_CACHE: Optional[dict] = None


def _help() -> dict:
    global _HELP_CACHE
    if _HELP_CACHE is None:
        text = load_vm_data_text("stratagy_sysparams_help.json",
                                 "EMBEDDED_VM_SYSPARAMS_HELP_JSON")
        try:
            _HELP_CACHE = (json.loads(text).get("params", {})) if text else {}
        except (ValueError, AttributeError):
            _HELP_CACHE = {}
    return _HELP_CACHE


def _unquote(value: str) -> str:
    v = value.strip()
    if len(v) >= 2 and v[0] == v[-1] and v[0] in "'\"":
        return v[1:-1]
    return v


def decode_shutdown(value: str) -> str:
    """'2 130' -> 'weekly, Tuesday 01:30' (day 0=Sunday, time HHMM)."""
    v = _unquote(value).split()
    if len(v) != 2 or not v[0].isdigit() or not v[1].isdigit():
        return value
    day = int(v[0])
    hhmm = v[1].zfill(4)
    day_name = _DAYS[day] if 0 <= day < 7 else f"day {day}"
    return f"weekly, {day_name} {hhmm[:2]}:{hhmm[2:]}"


def parse_install_cfg(text: str) -> dict:
    """Parse INSTALL.CFG into an ordered parameter grid + findings."""
    params: List[dict] = []
    groups: List[str] = []
    current_group = ""
    findings: List[dict] = []
    help_map = _help()

    for raw in text.replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        line = raw.rstrip()
        if not line:
            continue
        gm = _GROUP_RE.match(line)
        if gm and "set " not in line:
            current_group = gm.group(1)
            if current_group and current_group not in groups:
                groups.append(current_group)
            continue
        m = _SET_RE.match(line)
        if not m:
            continue
        disabled = bool(m.group(1))
        name = m.group(2)
        value = m.group(3)
        help_entry = help_map.get(name, {})
        params.append({
            "name": name,
            "value": _unquote(value),
            "raw_value": value,
            "enabled": not disabled,
            "group": current_group,
            "description": help_entry.get("description", ""),
            "possible": help_entry.get("possible", ""),
            "default": help_entry.get("default", ""),
            "decoded": decode_shutdown(value) if name == "shutdown" else None,
        })

    # security finding: cleartext default password left at the shipped value
    for p in params:
        if p["name"] == "password" and p["enabled"] and p["value"] == "Stratagy":
            findings.append({
                "severity": "high",
                "param": "password",
                "message": "System password is the shipped default 'Stratagy' "
                           "(stored in cleartext in INSTALL.CFG).",
            })

    return {"params": params, "groups": groups, "findings": findings,
            "help_status": "partial"}


def render_install_cfg(parsed: dict) -> str:
    """Serialise a parsed grid back to INSTALL.CFG text (P3 write path, gated).

    Preserves order, the `#`-disabled prefix and group headings; re-quotes a
    value that contains spaces, as the file does."""
    out: List[str] = []
    seen_groups = set()
    for p in parsed.get("params", []):
        group = p.get("group")
        if group and group not in seen_groups:
            seen_groups.add(group)
            out.append(f"#- {group}")
        value = p.get("raw_value")
        if value is None:
            v = p.get("value", "")
            value = f"'{v}'" if (" " in v) else v
        prefix = "" if p.get("enabled", True) else "#"
        out.append(f"{prefix}set {p['name']} {value}".rstrip())
    return "\r\n".join(out) + "\r\n"


def sysparams_from_blob(blob_text: str) -> dict:
    """Convenience: parse the `set` lines out of a reassembled content blob."""
    return parse_install_cfg(blob_text)


__all__ = ["parse_install_cfg", "render_install_cfg", "decode_shutdown",
           "sysparams_from_blob"]
vm_sysparams = sys.modules[__name__]  # flatten alias

# ===== vm_pbxdb.py =================================================
"""`<pbx_type>.PBX` — dial codes + SMDI integration patterns (read + compare).

The live ``C:\\Stratagy\\PBX.DB\\<model>.PBX`` comes back as **confirmed**
plaintext (voicemail-map §2.9): ``dl_*`` dial codes (value in Token language,
label after ``#``), ``pbx_name`` and ``integration NN '…'`` SMDI/in-band
pattern templates. :func:`compare_with_default` diffs the live file against the
bundled vendor template for the model — the Plug-and-Play menu's value shown as
a diff, never a rewrite. Read-only; nothing here writes to the card.
"""


import json
import re
from typing import Dict, List, Optional


_DL_RE = re.compile(r"^(dl_\w+)\s*([^#\r\n]*?)\s*(?:#\s*(.*?))?\s*$")
_INT_RE = re.compile(r"^integration\s+(\d+)\s+'([^']*)'")
_NAME_RE = re.compile(r"^pbx_name\s+'([^']*)'")

_DEFAULTS_CACHE: Optional[dict] = None


def _defaults() -> dict:
    global _DEFAULTS_CACHE
    if _DEFAULTS_CACHE is None:
        text = load_vm_data_text("stratagy_pbx_defaults.json",
                                 "EMBEDDED_VM_PBX_DEFAULTS_JSON")
        try:
            _DEFAULTS_CACHE = (json.loads(text).get("models", {})) if text else {}
        except (ValueError, AttributeError):
            _DEFAULTS_CACHE = {}
    return _DEFAULTS_CACHE


def parse_pbx(text: str) -> dict:
    """Parse a .PBX file into ``{pbx_name, dial_codes[], integration[]}``."""
    pbx_name = ""
    dial_codes: List[dict] = []
    integration: List[dict] = []
    for raw in text.replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        line = raw.rstrip()
        if not line:
            continue
        nm = _NAME_RE.match(line)
        if nm:
            pbx_name = nm.group(1)
            continue
        im = _INT_RE.match(line)
        if im:
            integration.append({"index": im.group(1), "pattern": im.group(2)})
            continue
        dm = _DL_RE.match(line)
        if dm and line.startswith("dl_"):
            dial_codes.append({
                "code": dm.group(1),
                "value": (dm.group(2) or "").strip(),
                "label": (dm.group(3) or "").strip().rstrip(":"),
            })
    return {"pbx_name": pbx_name, "dial_codes": dial_codes,
            "integration": integration}


def default_for(model: str) -> Optional[dict]:
    """The bundled vendor template for ``model``, parsed — or ``None``."""
    text = _defaults().get((model or "").strip())
    if text is None:
        # tolerate case / trailing-S variants
        for k, v in _defaults().items():
            if k.lower() == (model or "").strip().lower():
                text = v
                break
    return parse_pbx(text) if text is not None else None


def compare_with_default(live: dict, model: str) -> dict:
    """Diff a parsed live .PBX against the bundled model default.

    Returns per-section changes; ``available`` is False (with a reason) when no
    default is bundled for the model, so the UI says so rather than implying
    a clean match."""
    default = default_for(model)
    if default is None:
        return {"available": False,
                "reason": f"No bundled Toshiba default for model {model!r} yet.",
                "dial_codes": [], "integration": []}

    dl_changes = []
    live_dl = {d["code"]: d for d in live.get("dial_codes", [])}
    def_dl = {d["code"]: d for d in default.get("dial_codes", [])}
    for code in sorted(set(live_dl) | set(def_dl)):
        lv = (live_dl.get(code) or {}).get("value", "")
        dv = (def_dl.get(code) or {}).get("value", "")
        if code not in live_dl:
            dl_changes.append({"code": code, "kind": "removed",
                               "default": dv, "live": None})
        elif code not in def_dl:
            dl_changes.append({"code": code, "kind": "added",
                               "default": None, "live": lv})
        elif lv != dv:
            dl_changes.append({"code": code, "kind": "changed",
                               "default": dv, "live": lv,
                               "label": live_dl[code].get("label", "")})

    live_int = [i["pattern"] for i in live.get("integration", [])]
    def_int = [i["pattern"] for i in default.get("integration", [])]
    int_changes = []
    for p in live_int:
        if p not in def_int:
            int_changes.append({"pattern": p, "kind": "added"})
    for p in def_int:
        if p not in live_int:
            int_changes.append({"pattern": p, "kind": "removed"})

    return {"available": True, "model": model,
            "default_name": default.get("pbx_name", ""),
            "dial_codes": dl_changes, "integration": int_changes,
            "clean": not dl_changes and not int_changes}


def pbxdb_from_blob(blob_text: str) -> dict:
    """Parse the dial-code / integration lines out of a content blob."""
    return parse_pbx(blob_text)


__all__ = ["parse_pbx", "default_for", "compare_with_default", "pbxdb_from_blob"]
vm_pbxdb = sys.modules[__name__]  # flatten alias

# ===== vm_catalog.py ===============================================
"""The Stratagy mailbox field catalog (``data/stratagy_vm_catalog.json``).

The VM twin of the eManager program catalog: tab, label, tooltip, type, range,
wire location and **status** (`confirmed | inferred | unknown`). It drives the
read-only User Editor (status dots and inline help) and the write gate.

The one invariant (DESIGN_PLAN §8.4, voicemail-map §10): a field is editable
only when its status is ``confirmed`` **and** VM writes are enabled. P1 ships
read-only, so :func:`field_writable` returns ``False`` for everything until the
write path lands (P3); :func:`validate` proves no non-confirmed field could ever
present a writable control.
"""


import json
from typing import Dict, List, Optional


# P1 master switch: voicemail writes are OFF until the supervised lab write
# (DESIGN_PLAN §11 P3, voicemail-map §6.4). Nothing in P1 flips this.
VM_WRITES_ENABLED = False

_CACHE: Optional[dict] = None


def load_vm_catalog() -> dict:
    """Load + index the catalog: ``{tabs, fields, by_name, by_tab}``."""
    global _CACHE
    if _CACHE is not None:
        return _CACHE
    text = load_vm_data_text("stratagy_vm_catalog.json", "EMBEDDED_VM_CATALOG_JSON")
    data = json.loads(text) if text else {"tabs": [], "fields": []}
    fields = data.get("fields", [])
    by_name = {f["name"]: f for f in fields}
    by_tab: Dict[str, List[dict]] = {}
    for f in fields:
        by_tab.setdefault(f.get("tab", ""), []).append(f)
    _CACHE = {"tabs": data.get("tabs", list(by_tab.keys())),
              "fields": fields, "by_name": by_name, "by_tab": by_tab,
              "meta": data.get("_meta", {})}
    return _CACHE


def field_writable(field: dict, writes_enabled: bool = VM_WRITES_ENABLED) -> bool:
    """A field may be edited only if confirmed AND writes are globally on."""
    return bool(writes_enabled) and field.get("status") == "confirmed"


def status_dot(field: dict) -> str:
    """green (confirmed) | amber (inferred) | grey (unknown) — the editor dot."""
    return {"confirmed": "green", "inferred": "amber"}.get(
        field.get("status"), "grey")


def validate(catalog: Optional[dict] = None) -> List[str]:
    """Return catalog errors (empty = valid). Mirrors the design's test:

    every field has tab/label/type/status, and no non-``confirmed`` field is
    marked writable (it cannot present an editable control)."""
    cat = catalog or load_vm_catalog()
    errors: List[str] = []
    for f in cat.get("fields", []):
        for key in ("name", "tab", "label", "type", "status"):
            if not f.get(key):
                errors.append(f"field {f.get('name', '?')!r} missing {key}")
        if f.get("status") not in ("confirmed", "inferred", "unknown"):
            errors.append(f"field {f.get('name')!r} bad status {f.get('status')!r}")
        # the safety invariant: never writable unless confirmed
        if field_writable(f, writes_enabled=True) and f.get("status") != "confirmed":
            errors.append(f"field {f.get('name')!r} writable but not confirmed")
    return errors


def editor_model(writes_enabled: bool = VM_WRITES_ENABLED) -> dict:
    """The catalog shaped for the editor: tabs, each with its fields + dots."""
    cat = load_vm_catalog()
    tabs = []
    for tab in cat["tabs"]:
        fields = []
        for f in cat["by_tab"].get(tab, []):
            fields.append({**f, "dot": status_dot(f),
                           "writable": field_writable(f, writes_enabled)})
        tabs.append({"tab": tab, "fields": fields})
    return {"tabs": tabs, "writes_enabled": writes_enabled,
            "meta": cat.get("meta", {})}


__all__ = ["VM_WRITES_ENABLED", "load_vm_catalog", "field_writable",
           "status_dot", "validate", "editor_model"]
vm_catalog = sys.modules[__name__]  # flatten alias

# ===== vm_reports.py ===============================================
"""Mailbox reports — client-side, instant, over a read model (voicemail-map §5.6).

VM Manager's report is a **template** (an ordered column list over a User ID
range) run with optional *Reset Statistics*. Because the app holds every box in
memory after a read, *Run Report* is client-side and instant: no serial traffic,
no range re-read. *Reset Statistics* is the only part that needs a write and is
gated like any write (not in P1). Security codes are masked in report output.
"""


from typing import Dict, List, Optional

# Every column a report may list, with its display label and the mailbox-dict
# key it reads. Security code is intentionally masked (never dumped in a report).
COLUMNS: Dict[str, dict] = {
    "box": {"label": "User ID", "key": "box"},
    "comment": {"label": "Comment", "key": "comment"},
    "extension": {"label": "Extension", "key": "extension"},
    "name": {"label": "Name", "key": "name"},
    "security_code": {"label": "Security code", "key": "security_code", "mask": True},
    "created": {"label": "Box created", "key": "created"},
    "modified": {"label": "Box saved", "key": "modified"},
    "record_len": {"label": "Record bytes", "key": "record_len"},
}

TEMPLATES: List[dict] = [
    {"id": "directory", "name": "Directory",
     "columns": ["box", "name", "extension", "comment"]},
    {"id": "audit", "name": "Security audit",
     "columns": ["box", "name", "security_code", "modified"]},
    {"id": "full", "name": "Full mailbox list",
     "columns": ["box", "comment", "extension", "name", "created", "modified"]},
]


def default_templates() -> List[dict]:
    return [dict(t) for t in TEMPLATES]


def _in_range(box: str, lo: Optional[str], hi: Optional[str]) -> bool:
    try:
        n = int(box)
    except (TypeError, ValueError):
        return True
    if lo not in (None, "") and n < int(lo):
        return False
    if hi not in (None, "") and n > int(hi):
        return False
    return True


def run_report(template: dict, boxes: Dict[str, dict], *,
               first: Optional[str] = None, last: Optional[str] = None) -> dict:
    """Run a template over a read model's ``boxes`` map. Pure; no I/O."""
    cols = [c for c in template.get("columns", []) if c in COLUMNS]
    header = [{"name": c, "label": COLUMNS[c]["label"]} for c in cols]
    rows: List[List[str]] = []
    for box in sorted(boxes, key=lambda b: (len(b), b)):
        if not _in_range(box, first, last):
            continue
        rec = boxes[box]
        row = []
        for c in cols:
            spec = COLUMNS[c]
            val = rec.get(spec["key"])
            if spec.get("mask") and val:
                val = "••••"
            row.append("" if val is None else str(val))
        rows.append(row)
    return {"template": template.get("id"), "columns": header, "rows": rows,
            "row_count": len(rows)}


def to_csv(report: dict) -> str:
    """CSV text for Save/download (the old report export)."""
    import csv
    import io
    buf = io.StringIO()
    w = csv.writer(buf)
    w.writerow([c["label"] for c in report.get("columns", [])])
    for row in report.get("rows", []):
        w.writerow(row)
    return buf.getvalue()


__all__ = ["COLUMNS", "TEMPLATES", "default_templates", "run_report", "to_csv"]
vm_reports = sys.modules[__name__]  # flatten alias

# ===== vm_backup.py ================================================
"""Backup to JSON + mailbox-level diff — the no-call-interruption read path.

The native Backup/Restore Utility halts call processing and its serialization
is not yet captured (voicemail-map §5.5, §9). This module is the app's own
alternative: it reads every box, the system parameters and the dial-code/
integration table over **confirmed** opcodes **without stopping calls**, into a
plain JSON document, and diffs two of them per mailbox — decoded fields first,
with a **raw-bytes fallback** ("record changed, N bytes differ at offsets …")
so a changed security code is spotted before every flag offset is mapped. Read
only; this never writes to a card.
"""


from datetime import datetime
from typing import Dict, List, Optional


BACKUP_KIND = "stratagy-vm-json"
BACKUP_VERSION = 1


def read_model(link, *, progress=None) -> dict:
    """Read a full voicemail model over a :class:`~toshiba_cix.vm_link.VMLink`.

    ``progress(done, total, message)`` is called as boxes stream in (the
    determinate "Reading box N of M" bar). Returns decoded, JSON-ready data."""
    firmware = getattr(link, "firmware", "")
    admin_box = getattr(link, "admin_box", "")

    install_text = link.read_file("INSTALL.CFG").decode("latin-1", "replace")
    sysparams = vm_sysparams.parse_install_cfg(install_text)

    pbx_type = _param(sysparams, "pbx_type") or "CIX100S"
    pbxdb = {"pbx_name": "", "dial_codes": [], "integration": [],
             "model": pbx_type}
    try:
        pbx_text = link.read_file(f"C:\\Stratagy\\PBX.DB\\{pbx_type}.PBX").decode(
            "latin-1", "replace")
        if not pbx_text.strip():
            pbx_text = link.read_file(f"{pbx_type}.PBX").decode("latin-1", "replace")
        parsed = vm_pbxdb.parse_pbx(pbx_text)
        parsed["model"] = pbx_type
        pbxdb = parsed
    except Exception:  # noqa: BLE001 — a missing .PBX leaves the table empty
        pass

    directory = link.read_directory()
    boxes: Dict[str, dict] = {}
    total = len(directory)
    for i, box in enumerate(sorted(directory, key=lambda b: (len(b), b)), 1):
        if progress:
            progress(i, total, f"Reading box {box} ({i} of {total})")
        try:
            mb = vm_records.read_mailbox(link, box)
            if not mb.name:
                mb.name = directory[box]
            boxes[box] = mb.as_dict()
        except Exception as exc:  # noqa: BLE001 — record a read error, keep going
            boxes[box] = {"box": box, "name": directory.get(box, ""),
                          "error": str(exc)}
    return {"firmware": firmware, "admin_box": admin_box,
            "sysparams": sysparams, "pbxdb": pbxdb,
            "directory": directory, "boxes": boxes}


def build_json_backup(link, *, site: Optional[str] = None, progress=None) -> dict:
    """A full JSON backup document (meta + the read model)."""
    model = read_model(link, progress=progress)
    return {
        "meta": {
            "kind": BACKUP_KIND,
            "backup_version": BACKUP_VERSION,
            "tool_version": __version__,
            "taken_at": datetime.utcnow().isoformat() + "Z",
            "site": site,
            "firmware": model.get("firmware", ""),
            "box_count": len(model.get("boxes", {})),
            "note": "read over confirmed opcodes without interrupting calls",
        },
        **model,
    }


# -- mailbox-level diff -----------------------------------------------------
_DIFF_FIELDS = ["name", "extension", "comment", "security_code",
                "created", "modified"]


def _raw_byte_diff(a_hex: str, b_hex: str) -> Optional[dict]:
    """Where two raw segments differ, for the fallback line."""
    if not a_hex or not b_hex:
        return None
    a = bytes.fromhex(a_hex)
    b = bytes.fromhex(b_hex)
    if a == b:
        return None
    offsets = [i for i in range(min(len(a), len(b))) if a[i] != b[i]]
    if len(a) != len(b):
        offsets.append(min(len(a), len(b)))
    return {"bytes_differ": len(offsets),
            "offsets": offsets[:16],
            "len_a": len(a), "len_b": len(b)}


def diff_mailbox(a: dict, b: dict) -> dict:
    """Per-box diff: decoded field changes first, raw-bytes fallback second."""
    changes = []
    for f in _DIFF_FIELDS:
        av, bv = a.get(f), b.get(f)
        if av != bv:
            sensitive = f == "security_code"
            changes.append({
                "field": f,
                "old": "••••" if sensitive and av else av,
                "new": "••••" if sensitive and bv else bv,
                "sensitive": sensitive,
            })
    raw = {}
    for seg in ("raw_props_hex", "raw_ua_hex"):
        rd = _raw_byte_diff(a.get(seg, ""), b.get(seg, ""))
        if rd:
            raw[seg] = rd
    return {"changes": changes, "raw": raw,
            "changed": bool(changes or raw)}


def diff_backups(a: dict, b: dict) -> dict:
    """Diff two JSON backups (or two read models) at the mailbox level."""
    a_boxes = a.get("boxes", {})
    b_boxes = b.get("boxes", {})
    added = sorted(set(b_boxes) - set(a_boxes), key=lambda x: (len(x), x))
    removed = sorted(set(a_boxes) - set(b_boxes), key=lambda x: (len(x), x))
    changed = {}
    for box in sorted(set(a_boxes) & set(b_boxes), key=lambda x: (len(x), x)):
        d = diff_mailbox(a_boxes[box], b_boxes[box])
        if d["changed"]:
            changed[box] = d
    sys_a = {p["name"]: p["value"] for p in a.get("sysparams", {}).get("params", [])}
    sys_b = {p["name"]: p["value"] for p in b.get("sysparams", {}).get("params", [])}
    sys_changed = [{"name": n, "old": sys_a.get(n), "new": sys_b.get(n)}
                   for n in sorted(set(sys_a) | set(sys_b))
                   if sys_a.get(n) != sys_b.get(n)]
    return {"added": added, "removed": removed, "boxes": changed,
            "sysparams": sys_changed,
            "summary": {"boxes_added": len(added), "boxes_removed": len(removed),
                        "boxes_changed": len(changed),
                        "sysparams_changed": len(sys_changed)}}


def _param(sysparams: dict, name: str) -> Optional[str]:
    for p in sysparams.get("params", []):
        if p["name"] == name and p["enabled"]:
            return p["value"]
    return None


__all__ = ["read_model", "build_json_backup", "diff_backups", "diff_mailbox",
           "BACKUP_KIND", "BACKUP_VERSION"]
vm_backup = sys.modules[__name__]  # flatten alias

# ===== vm_session.py ===============================================
"""The one exclusive voicemail session the server owns.

The LVMU serial session is **stateful and exclusive** — the card refuses a
second admin login (voicemail-map §3.5) — so the server holds exactly one
:class:`VmSession` per process, every VM request goes through its lock, and the
decoded model is cached per session with a single explicit *Refresh* (never
polling the serial line). All reads use confirmed opcodes; the save surface is
**plan-only** (two-phase contract + Simulate) and performs no hardware write in
P1.

Offline, ``transport="fake"`` drives the :class:`~toshiba_cix.vm_link.FakeLVMU`
protocol twin so the whole UI and its tests run with no hardware.
"""


import threading
from typing import Dict, Optional


# Map decoded-mailbox keys to catalog field names (the editor reads values here).
_VALUE_MAP = {
    "box": "user_id", "comment": "comment", "extension": "extension",
    "name": "name1", "security_code": "security_code",
    "created": "box_created", "modified": "box_saved",
}


class VmSession:
    def __init__(self):
        self._lock = threading.RLock()
        self._link: Optional[vm_link.VMLink] = None
        self.transport_name = ""
        self.transport_kind = ""
        # per-session caches
        self._directory: Optional[Dict[str, str]] = None
        self._boxes: Dict[str, dict] = {}
        self._sysparams: Optional[dict] = None
        self._pbxdb: Optional[dict] = None

    # -- lifecycle --------------------------------------------------------
    def connect(self, spec: dict) -> dict:
        with self._lock:
            self.disconnect()
            kind = (spec or {}).get("transport") or "serial"
            if kind == "fake":
                transport = vm_link.FakeLVMU()
            else:
                transport = vm_serial.open_transport(spec)
            link = vm_link.VMLink(transport, password=spec.get("password")
                                  or "Stratagy")
            link.connect()  # banner -> login -> preamble (raises on failure)
            self._link = link
            self.transport_kind = kind
            self.transport_name = getattr(transport, "name", kind)
            self._clear_cache()
            return self.status()

    def disconnect(self) -> None:
        with self._lock:
            if self._link is not None:
                self._link.close()
            self._link = None
            self._clear_cache()

    def _clear_cache(self) -> None:
        self._directory = None
        self._boxes = {}
        self._sysparams = None
        self._pbxdb = None

    @property
    def connected(self) -> bool:
        return self._link is not None and self._link.connected

    def _require(self) -> vm_link.VMLink:
        if not self.connected:
            raise VmNotConnected("no voicemail session — Connect first")
        return self._link  # type: ignore[return-value]

    # -- status -----------------------------------------------------------
    def status(self) -> dict:
        link = self._link
        return {
            "connected": self.connected,
            "transport": self.transport_kind,
            "port": self.transport_name,
            "firmware": getattr(link, "firmware", "") if link else "",
            "admin_box": getattr(link, "admin_box", "") if link else "",
            "log_name": getattr(link, "log_name", "") if link else "",
            "trace_frames": len(link.trace) if link else 0,
            "shutdown": self._shutdown_text(),
            "writes_enabled": vm_catalog.VM_WRITES_ENABLED,
        }

    def _shutdown_text(self) -> Optional[str]:
        sp = self._sysparams
        if not sp:
            return None
        for p in sp.get("params", []):
            if p["name"] == "shutdown" and p["enabled"]:
                return p.get("decoded") or p.get("value")
        return None

    # -- reads ------------------------------------------------------------
    def directory(self, refresh: bool = False) -> Dict[str, str]:
        with self._lock:
            link = self._require()
            if self._directory is None or refresh:
                self._directory = link.read_directory()
                if refresh:
                    self._boxes = {}
            return self._directory

    def boxes(self, refresh: bool = False) -> list:
        """The Box List: User ID | Comment | Extension | Name | Messages,
        reserved boxes (411, 990-999) flagged muted, never hidden."""
        directory = self.directory(refresh=refresh)
        rows = []
        for box in sorted(directory, key=lambda b: (len(b), b)):
            rows.append({
                "box": box,
                "name": directory[box],
                "reserved": _is_reserved(box),
            })
        return rows

    def box(self, box_id: str, refresh: bool = False) -> dict:
        with self._lock:
            link = self._require()
            if box_id not in self._boxes or refresh:
                mb = vm_records.read_mailbox(link, box_id)
                if not mb.name:
                    mb.name = (self._directory or {}).get(box_id, "")
                self._boxes[box_id] = mb.as_dict()
            rec = self._boxes[box_id]
            return {"mailbox": rec, "editor": self._editor_for(rec),
                    "reserved": _is_reserved(box_id)}

    def _editor_for(self, rec: dict) -> dict:
        """The catalog editor model with this box's confirmed values filled in."""
        model = vm_catalog.editor_model()
        values = {}
        for mkey, fname in _VALUE_MAP.items():
            if rec.get(mkey) not in (None, ""):
                values[fname] = rec.get(mkey)
        model["values"] = values
        return model

    def sysparams(self, refresh: bool = False) -> dict:
        with self._lock:
            link = self._require()
            if self._sysparams is None or refresh:
                text = link.read_file("INSTALL.CFG").decode("latin-1", "replace")
                self._sysparams = vm_sysparams.parse_install_cfg(text)
            return self._sysparams

    def pbxdb(self, refresh: bool = False, compare: bool = False) -> dict:
        with self._lock:
            link = self._require()
            if self._pbxdb is None or refresh:
                sp = self.sysparams()
                model = _param(sp, "pbx_type") or "CIX100S"
                text = ""
                for path in (f"C:\\Stratagy\\PBX.DB\\{model}.PBX", f"{model}.PBX"):
                    try:
                        text = link.read_file(path).decode("latin-1", "replace")
                    except Exception:  # noqa: BLE001
                        text = ""
                    if text.strip():
                        break
                parsed = vm_pbxdb.parse_pbx(text)
                parsed["model"] = model
                self._pbxdb = parsed
            result = dict(self._pbxdb)
            if compare:
                result["compare"] = vm_pbxdb.compare_with_default(
                    self._pbxdb, self._pbxdb.get("model", ""))
            return result

    def backup_json(self, *, site: Optional[str] = None, progress=None) -> dict:
        with self._lock:
            link = self._require()
            doc = vm_backup.build_json_backup(link, site=site, progress=progress)
            # warm the per-box cache from the backup read
            self._boxes.update(doc.get("boxes", {}))
            self._directory = doc.get("directory", self._directory)
            self._sysparams = doc.get("sysparams", self._sysparams)
            return doc

    def run_report(self, template_id: str, *, first=None, last=None) -> dict:
        with self._lock:
            tmpls = {t["id"]: t for t in vm_reports.default_templates()}
            tmpl = tmpls.get(template_id)
            if tmpl is None:
                raise ValueError(f"unknown report template {template_id!r}")
            # Reports are client-side over a full read (voicemail-map §5.6): make
            # sure every box is in the cache, not just ones opened individually.
            directory = self.directory()
            full = {b for b, r in self._boxes.items() if "error" not in r}
            if not directory or not full.issuperset(directory):
                self.backup_json()
            return vm_reports.run_report(tmpl, self._boxes, first=first, last=last)

    def trace_text(self) -> str:
        link = self._link
        return link.trace_text() if link else ""

    # -- plan-only save (two-phase; Simulate; no hardware write in P1) ----
    def plan_save(self, box_id: str, changes: dict) -> dict:
        """Compute a preview of the record patch WITHOUT writing.

        This is the *plan* phase of plan->review->apply. P1 never applies: the
        write path is gated behind VM_WRITES_ENABLED (OFF) and a supervised lab
        write (voicemail-map §6.4). Only confirmed-offset fields can even be
        planned; everything else is refused with its reason."""
        with self._lock:
            info = self.box(box_id)
            rec = info["mailbox"]
            cat = vm_catalog.load_vm_catalog()["by_name"]
            planned, refused = [], []
            ua_hex = rec.get("raw_ua_hex", "")
            for fname, new_value in (changes or {}).items():
                field = cat.get(fname, {})
                if field.get("status") != "confirmed":
                    refused.append({"field": fname, "reason":
                                    "field offset unverified — read-only in this "
                                    "version"})
                    continue
                if fname == "security_code" and ua_hex:
                    try:
                        before = bytes.fromhex(ua_hex)
                        after = vm_records.rewrite_security_code(
                            before, str(new_value))
                        planned.append({
                            "field": fname, "old": "••••", "new": "••••",
                            "wire": "UA segment (patch-in-place, length-preserving)",
                            "bytes_changed": sum(1 for x, y in zip(before, after)
                                                 if x != y),
                            "proven": False,
                            "note": "write UNCONFIRMED against hardware — "
                                    "requires a supervised lab write (P3)",
                        })
                    except ValueError as exc:
                        refused.append({"field": fname, "reason": str(exc)})
                else:
                    planned.append({"field": fname, "old": rec.get(fname),
                                    "new": new_value, "proven": True})
            return {
                "box": box_id,
                "mode": "simulate",
                "writes_enabled": vm_catalog.VM_WRITES_ENABLED,
                "planned": planned,
                "refused": refused,
                "apply_allowed": False,
                "reason": ("Voicemail writes are disabled in this release "
                           "(read-only). This is a preview only."),
            }


class VmNotConnected(RuntimeError):
    pass


def _is_reserved(box: str) -> bool:
    try:
        n = int(box)
    except (TypeError, ValueError):
        return True  # named system boxes (GREETING, SOFTMODEM, …)
    return n == 411 or 990 <= n <= 999


def _param(sysparams: dict, name: str) -> Optional[str]:
    for p in sysparams.get("params", []):
        if p["name"] == name and p["enabled"]:
            return p["value"]
    return None


class VmSessionManager:
    """One process-wide exclusive VM session (the card allows only one)."""

    def __init__(self):
        self.session = VmSession()


__all__ = ["VmSession", "VmSessionManager", "VmNotConnected"]
vm_session = sys.modules[__name__]  # flatten alias

# ===== appdirs.py ==================================================
"""Per-OS store root for Switchroom — one name, ``<store root>``, everywhere.

Three design docs named three different store paths; this module is the single
place that resolves them (DESIGN_PLAN 2.1, decision #8). It is pure stdlib — no
``platformdirs`` — and fully I/O-injected: ``store_root`` takes ``env`` /
``platform`` / ``argv0`` so a test pins a temp directory without touching the
real user profile.

| OS | Default ``<store root>`` |
|----|--------------------------|
| Windows | ``%APPDATA%\\Switchroom`` |
| macOS   | ``~/Library/Application Support/Switchroom`` |
| Linux   | ``$XDG_DATA_HOME/switchroom`` or ``~/.local/share/switchroom`` |

``--portable`` (``portable=True``) puts the store **beside the executable** so
the whole tool runs from a USB stick. Under the root live ``sites.json``,
``pending-<site>.json``, ``journal.sqlite`` + ``changes.log``, ``settings.json``,
``backups/<site>/...`` and ``logs/app.log`` (architecture.md 4.3).
"""


import os
import sys

APP_NAME = "Switchroom"            # product name (DESIGN_PLAN decision #7)
APP_DIR_POSIX = "switchroom"       # lowercase for the XDG path


def _home_dir(env: dict) -> str:
    return env.get("HOME") or env.get("USERPROFILE") or os.path.expanduser("~")


def default_root(*, env=None, platform=None) -> str:
    """The per-OS default store root (not created). Pure; inputs injectable."""
    env = os.environ if env is None else env
    platform = sys.platform if platform is None else platform
    if platform.startswith("win"):
        base = env.get("APPDATA") or os.path.join(_home_dir(env), "AppData", "Roaming")
        return os.path.join(base, APP_NAME)
    if platform == "darwin":
        return os.path.join(_home_dir(env), "Library", "Application Support", APP_NAME)
    base = env.get("XDG_DATA_HOME") or os.path.join(_home_dir(env), ".local", "share")
    return os.path.join(base, APP_DIR_POSIX)


def portable_root(*, argv0=None) -> str:
    """The store beside the running executable / script (``--portable``)."""
    exe = argv0
    if exe is None:
        exe = sys.executable if getattr(sys, "frozen", False) else (sys.argv[0] or ".")
    base = os.path.dirname(os.path.abspath(exe))
    return os.path.join(base, APP_NAME)


def store_root(*, portable=False, override=None, env=None, platform=None,
               argv0=None) -> str:
    """Resolve the store root: explicit override > portable > per-OS default."""
    if override:
        return os.path.abspath(os.path.expanduser(override))
    if portable:
        return portable_root(argv0=argv0)
    return default_root(env=env, platform=platform)


class AppDirs:
    """Resolved store root with the standard file/dir layout and ``ensure()``.

    Paths are computed lazily and nothing is written until :meth:`ensure`
    (or a path-returning helper with ``create=True``) is called, so
    constructing an :class:`AppDirs` for a test is side-effect free.
    """

    def __init__(self, root: str):
        self.root = os.path.abspath(os.path.expanduser(root))

    # -- top-level files ---------------------------------------------------
    @property
    def sites_file(self) -> str:
        return os.path.join(self.root, "sites.json")

    @property
    def journal_db(self) -> str:
        return os.path.join(self.root, "journal.sqlite")

    @property
    def changes_log(self) -> str:
        return os.path.join(self.root, "changes.log")

    @property
    def settings_file(self) -> str:
        return os.path.join(self.root, "settings.json")

    def pending_file(self, site_id: str) -> str:
        return os.path.join(self.root, f"pending-{_safe_component(site_id)}.json")

    # -- sub-directories ---------------------------------------------------
    @property
    def backups_dir(self) -> str:
        return os.path.join(self.root, "backups")

    def site_backups_dir(self, site_id: str) -> str:
        return os.path.join(self.backups_dir, _safe_component(site_id))

    @property
    def logs_dir(self) -> str:
        return os.path.join(self.root, "logs")

    @property
    def log_file(self) -> str:
        return os.path.join(self.logs_dir, "app.log")

    # -- creation ----------------------------------------------------------
    def ensure(self) -> "AppDirs":
        """Create the root, ``backups/`` and ``logs/`` (mode 0700). Idempotent."""
        for d in (self.root, self.backups_dir, self.logs_dir):
            os.makedirs(d, exist_ok=True)
            _chmod_private_dir(d)
        return self

    def ensure_site_backups(self, site_id: str) -> str:
        d = self.site_backups_dir(site_id)
        os.makedirs(d, exist_ok=True)
        return d

    def __repr__(self) -> str:  # pragma: no cover
        return f"AppDirs({self.root!r})"


def from_args(*, portable=False, override=None, env=None, platform=None,
              argv0=None) -> AppDirs:
    """Convenience: resolve the root and wrap it in :class:`AppDirs`."""
    return AppDirs(store_root(portable=portable, override=override, env=env,
                              platform=platform, argv0=argv0))


# --------------------------------------------------------------------------
# helpers
# --------------------------------------------------------------------------
def _safe_component(name: str) -> str:
    """A filename-safe slug for a site id used in a path component."""
    keep = "-_."
    s = "".join(c if (c.isalnum() or c in keep) else "-" for c in str(name))
    return s.strip("-") or "site"


def _chmod_private_dir(path: str) -> None:
    """Best-effort 0700 on POSIX; a no-op where chmod is meaningless (Windows)."""
    try:
        if not sys.platform.startswith("win"):
            os.chmod(path, 0o700)
    except OSError:  # pragma: no cover
        pass


__all__ = [
    "APP_NAME", "APP_DIR_POSIX", "AppDirs",
    "default_root", "portable_root", "store_root", "from_args",
]

# ===== sites.py ====================================================
"""The site book — ``sites.json``, the tech's equipment list.

A **site** is one customer system (eManager "Client Equipment" ∪ VM Manager
"Connection") with two legs — a PBX leg over SNMP and a Voice Mail leg over
serial/TCP — in the shape DESIGN_PLAN 2.3 fixes::

    {"id": "104670-tonerfarms", "name": "104670 Toner Farms — CIX100",
     "pbx": {"host": "...", "port": 161, "community": "...", "via": "overlay",
             "direct_host": "...", "identity": {...}},
     "vm":  {"transport": "tcp", "host": "...", "port": 7001,
             "direct_port": "COM3", "stratagy_type": "LVMU", "baud": 9600,
             "password_ref": "ask"},
     "notes": "...", "conduit_component_id": 1234,
     "flags": {"integer_write_proven": false, "persistence_verified": null},
     "vm_templates": []}

This module is pure stdlib and I/O-injected: :class:`SiteBook` takes an explicit
path, so a test drives it against a temp file. The file is written atomically
and ``0600`` — it holds community strings and (optionally) the Stratagy
password because the tool is useless without them, but **Conduit's credential
store stays the system of record** (architecture.md 3.1).
"""


import json
import os
import re
import sys
import tempfile

_VIA = ("direct", "overlay", "agent")


def slugify_id(name: str) -> str:
    """A stable, filename-safe id from a site name (``104670 Toner Farms`` ->
    ``104670-toner-farms``)."""
    s = str(name or "").strip().lower()
    s = re.sub(r"[^a-z0-9]+", "-", s)
    return s.strip("-") or "site"


def new_site(name: str, *, id=None, pbx=None, vm=None, notes="",
             conduit_component_id=None) -> dict:
    """Build a normalised site record (does not persist it)."""
    return normalize_site({
        "id": id or slugify_id(name),
        "name": name,
        "pbx": pbx or {},
        "vm": vm or {},
        "notes": notes,
        "conduit_component_id": conduit_component_id,
    })


def normalize_site(site: dict) -> dict:
    """Return a copy with every expected key present and legs shaped.

    Lenient on input (unknown keys are preserved); only fills defaults and
    coerces the two legs so downstream code never guards for missing keys.
    """
    s = dict(site or {})
    s["id"] = str(s.get("id") or slugify_id(s.get("name", "")))
    s["name"] = s.get("name") or s["id"]
    s["notes"] = s.get("notes") or ""
    s.setdefault("conduit_component_id", None)

    pbx = dict(s.get("pbx") or {})
    pbx.setdefault("host", pbx.get("host"))
    pbx.setdefault("port", pbx.get("port") or 161)
    pbx.setdefault("community", pbx.get("community") or "communityName")
    pbx.setdefault("via", pbx.get("via") if pbx.get("via") in _VIA else "direct")
    s["pbx"] = pbx

    vm = dict(s.get("vm") or {})
    vm.setdefault("transport", vm.get("transport") or "serial")
    vm.setdefault("baud", vm.get("baud") or 9600)
    vm.setdefault("stratagy_type", vm.get("stratagy_type") or "LVMU")
    s["vm"] = vm

    flags = dict(s.get("flags") or {})
    flags.setdefault("integer_write_proven", False)
    flags.setdefault("persistence_verified", None)
    s["flags"] = flags

    s.setdefault("vm_templates", list(s.get("vm_templates") or []))
    return s


class SiteBook:
    """Load / query / mutate ``sites.json`` at a given path. I/O-injected."""

    def __init__(self, path: str):
        self.path = path

    # -- read --------------------------------------------------------------
    def load(self) -> list[dict]:
        """Every site, normalised. Missing / empty / corrupt file -> ``[]``."""
        try:
            with open(self.path, encoding="utf-8") as fh:
                raw = json.load(fh)
        except (FileNotFoundError, ValueError):
            return []
        sites = raw.get("sites") if isinstance(raw, dict) else raw
        if not isinstance(sites, list):
            return []
        return [normalize_site(s) for s in sites if isinstance(s, dict)]

    def get(self, site_id: str):
        for s in self.load():
            if s["id"] == site_id:
                return s
        return None

    # -- write -------------------------------------------------------------
    def save_all(self, sites) -> list[dict]:
        """Replace the whole book (normalising each) and persist atomically."""
        out = [normalize_site(s) for s in sites]
        self._write(out)
        return out

    def upsert(self, site: dict) -> dict:
        """Insert or replace a site by id; returns the normalised record."""
        s = normalize_site(site)
        sites = self.load()
        for i, existing in enumerate(sites):
            if existing["id"] == s["id"]:
                sites[i] = s
                break
        else:
            sites.append(s)
        self._write(sites)
        return s

    def delete(self, site_id: str) -> bool:
        sites = self.load()
        kept = [s for s in sites if s["id"] != site_id]
        if len(kept) == len(sites):
            return False
        self._write(kept)
        return True

    # -- internals ---------------------------------------------------------
    def _write(self, sites: list[dict]) -> None:
        payload = json.dumps({"sites": sites}, indent=2, ensure_ascii=False) + "\n"
        d = os.path.dirname(os.path.abspath(self.path)) or "."
        os.makedirs(d, exist_ok=True)
        fd, tmp = tempfile.mkstemp(prefix=".sites-", dir=d)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                fh.write(payload)
            _chmod_private_file(tmp)
            os.replace(tmp, self.path)
        finally:
            if os.path.exists(tmp):
                os.unlink(tmp)


def sitebook_from_root(root) -> SiteBook:
    """A :class:`SiteBook` at ``<root>/sites.json`` (``root`` is a path or AppDirs)."""
    path = root.sites_file if hasattr(root, "sites_file") \
        else os.path.join(str(root), "sites.json")
    return SiteBook(path)


def _chmod_private_file(path: str) -> None:
    try:
        if not sys.platform.startswith("win"):
            os.chmod(path, 0o600)
    except OSError:  # pragma: no cover
        pass


__all__ = ["SiteBook", "slugify_id", "new_site", "normalize_site", "sitebook_from_root"]

# ===== journal.py ==================================================
"""The change journal — ``journal.sqlite`` + a human ``changes.log``.

Every commit (including a cancelled preview, recorded as ``mode=preview``) and
every read-back goes here (DESIGN_PLAN safety layer 10; architecture.md 4.3).
Two tables::

    commits(id, site, device_identity, started, finished, mode, transport,
            user, snapshot_path, ok)
    ops(commit_id, program, idx, field, oid, old, new, read_back, match)

``idx`` holds the row index (``index`` is a SQL keyword); it is surfaced as
``index`` in the dicts this module returns. A plain-text ``changes.log`` is
appended alongside because techs grep. Pure stdlib (``sqlite3``) and
path-injected: :class:`Journal` takes a db path (``":memory:"`` for tests) and
an optional log path.
"""


import json
import os
import sqlite3
from datetime import datetime, timezone

_SCHEMA = """
CREATE TABLE IF NOT EXISTS commits (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    site            TEXT,
    device_identity TEXT,
    started         TEXT,
    finished        TEXT,
    mode            TEXT,
    transport       TEXT,
    user            TEXT,
    snapshot_path   TEXT,
    ok              INTEGER
);
CREATE TABLE IF NOT EXISTS ops (
    commit_id INTEGER REFERENCES commits(id),
    program   TEXT,
    idx       TEXT,
    field     TEXT,
    oid       TEXT,
    old       TEXT,
    new       TEXT,
    read_back TEXT,
    match     INTEGER
);
CREATE INDEX IF NOT EXISTS ix_ops_commit ON ops(commit_id);
"""


def _utc_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def _json_scalar(v):
    """Store non-scalars as JSON so old/new/read_back survive a list or dict."""
    if v is None or isinstance(v, (str, int, float)):
        return v
    return json.dumps(v, default=str)


class Journal:
    """A sqlite commit journal with a sidecar human log. Path-injected."""

    def __init__(self, db_path: str, changes_log: str | None = None):
        self.db_path = db_path
        self.changes_log = changes_log
        if db_path != ":memory:":
            d = os.path.dirname(os.path.abspath(db_path)) or "."
            os.makedirs(d, exist_ok=True)
        self._conn = sqlite3.connect(db_path)
        self._conn.row_factory = sqlite3.Row
        self._conn.executescript(_SCHEMA)
        self._conn.commit()

    # -- write -------------------------------------------------------------
    def start_commit(self, *, site, mode="write", transport=None,
                     device_identity=None, user=None, snapshot_path=None) -> int:
        """Open a commit row and return its id. ``started`` is stamped now."""
        cur = self._conn.execute(
            "INSERT INTO commits (site, device_identity, started, mode, "
            "transport, user, snapshot_path, ok) VALUES (?,?,?,?,?,?,?,?)",
            (site, device_identity, _utc_now(), mode, transport, user,
             snapshot_path, None))
        self._conn.commit()
        return int(cur.lastrowid)

    def add_op(self, commit_id: int, *, program=None, index=None, field=None,
               oid=None, old=None, new=None, read_back=None, match=None) -> None:
        self._conn.execute(
            "INSERT INTO ops (commit_id, program, idx, field, oid, old, new, "
            "read_back, match) VALUES (?,?,?,?,?,?,?,?,?)",
            (commit_id, program, (None if index is None else str(index)), field,
             oid, _json_scalar(old), _json_scalar(new), _json_scalar(read_back),
             (None if match is None else int(bool(match)))))
        self._conn.commit()

    def add_ops(self, commit_id: int, ops) -> None:
        for op in ops:
            self.add_op(commit_id, **op)

    def finish_commit(self, commit_id: int, *, ok: bool,
                      finished: str | None = None) -> None:
        self._conn.execute(
            "UPDATE commits SET finished=?, ok=? WHERE id=?",
            (finished or _utc_now(), int(bool(ok)), commit_id))
        self._conn.commit()

    def log_line(self, text: str) -> None:
        """Append a line to ``changes.log`` (best-effort; never raises)."""
        if not self.changes_log:
            return
        try:
            d = os.path.dirname(os.path.abspath(self.changes_log)) or "."
            os.makedirs(d, exist_ok=True)
            with open(self.changes_log, "a", encoding="utf-8") as fh:
                fh.write(f"{_utc_now()}  {text}\n")
        except OSError:  # pragma: no cover
            pass

    # -- read --------------------------------------------------------------
    def list_commits(self, limit: int = 100) -> list[dict]:
        rows = self._conn.execute(
            "SELECT * FROM commits ORDER BY id DESC LIMIT ?", (limit,))
        return [self._commit_dict(r) for r in rows]

    def get_commit(self, commit_id: int) -> dict | None:
        row = self._conn.execute(
            "SELECT * FROM commits WHERE id=?", (commit_id,)).fetchone()
        if row is None:
            return None
        d = self._commit_dict(row)
        d["ops"] = self.ops_for(commit_id)
        return d

    def ops_for(self, commit_id: int) -> list[dict]:
        rows = self._conn.execute(
            "SELECT * FROM ops WHERE commit_id=? ORDER BY rowid", (commit_id,))
        return [self._op_dict(r) for r in rows]

    def close(self) -> None:
        self._conn.close()

    # -- row mapping -------------------------------------------------------
    @staticmethod
    def _commit_dict(r: sqlite3.Row) -> dict:
        d = dict(r)
        if d.get("ok") is not None:
            d["ok"] = bool(d["ok"])
        return d

    @staticmethod
    def _op_dict(r: sqlite3.Row) -> dict:
        d = dict(r)
        d["index"] = d.pop("idx", None)
        if d.get("match") is not None:
            d["match"] = bool(d["match"])
        return d


def journal_from_root(root) -> Journal:
    """A :class:`Journal` at ``<root>/journal.sqlite`` + ``<root>/changes.log``."""
    if hasattr(root, "journal_db"):
        return Journal(root.journal_db, root.changes_log)
    base = str(root)
    return Journal(os.path.join(base, "journal.sqlite"),
                   os.path.join(base, "changes.log"))


__all__ = ["Journal", "journal_from_root"]

# ===== server/events.py ============================================
"""The SSE event bus — the one push channel to the UI (``GET /api/events``).

A single daemon serves one local browser, so this is a small in-process
pub/sub: each subscriber gets a bounded :class:`queue.Queue`; :meth:`publish`
fans an event out to every live subscriber without blocking the publisher (a
full queue drops the oldest event rather than stall the engine). The handler
turns a subscription into the ``text/event-stream`` wire format.

Event types (DESIGN_PLAN 10.3, architecture.md 4.2): ``job.progress``,
``job.done``, ``job.error``, ``session.mode``, ``session.identity``,
``vm.link``. The payload is any JSON-serialisable dict.

Pure stdlib, thread-safe, I/O-free — the handler owns the socket.
"""


import json
import threading
from queue import Empty, Full, Queue

# A heartbeat the handler can send so a proxy / the browser keeps the stream
# open through idle periods; also how it notices a dropped client.
HEARTBEAT = ":keepalive"


class Subscription:
    """One live SSE client's queue. Iterate :meth:`events` to drain it."""

    def __init__(self, bus: "EventBus", maxsize: int = 1000):
        self._bus = bus
        self._q: "Queue[str]" = Queue(maxsize=maxsize)
        self.closed = False

    def put(self, frame: str) -> None:
        try:
            self._q.put_nowait(frame)
        except Full:
            # Never block the publisher: drop the oldest, enqueue the newest.
            try:
                self._q.get_nowait()
            except Empty:
                pass
            try:
                self._q.put_nowait(frame)
            except Full:  # pragma: no cover
                pass

    def get(self, timeout: float):
        """Next frame, or ``None`` on timeout (so the caller can heartbeat)."""
        try:
            return self._q.get(timeout=timeout)
        except Empty:
            return None

    def close(self) -> None:
        self.closed = True
        self._bus.unsubscribe(self)


class EventBus:
    """Fan events out to every live :class:`Subscription`. Thread-safe."""

    def __init__(self):
        self._subs: list[Subscription] = []
        self._lock = threading.Lock()
        self._on_count_change = None

    def on_count_change(self, callback) -> None:
        """Register a ``callback(count)`` fired when subscriber count changes.

        The daemon's auto-exit watcher uses this to start/cancel its timer.
        """
        self._on_count_change = callback

    def subscribe(self) -> Subscription:
        sub = Subscription(self)
        with self._lock:
            self._subs.append(sub)
            count = len(self._subs)
        self._notify(count)
        return sub

    def unsubscribe(self, sub: Subscription) -> None:
        with self._lock:
            if sub in self._subs:
                self._subs.remove(sub)
            count = len(self._subs)
        self._notify(count)

    def subscriber_count(self) -> int:
        with self._lock:
            return len(self._subs)

    def publish(self, event: str, data=None) -> None:
        """Enqueue ``event`` (+ optional JSON ``data``) on every subscriber."""
        frame = format_sse(event, data)
        with self._lock:
            subs = list(self._subs)
        for sub in subs:
            sub.put(frame)

    def _notify(self, count: int) -> None:
        cb = self._on_count_change
        if cb:
            try:
                cb(count)
            except Exception:  # noqa: BLE001  — a watcher error must not break pub/sub
                pass


def format_sse(event: str, data=None) -> str:
    """One SSE frame: ``event:`` + ``data:`` + blank-line terminator."""
    payload = json.dumps(data if data is not None else {}, default=str)
    return f"event: {event}\ndata: {payload}\n\n"


__all__ = ["EventBus", "Subscription", "format_sse", "HEARTBEAT"]

# ===== server/auth.py ==============================================
"""Loopback token + Origin/Host guard — the first and most important PR.

Today's ``/api/save`` and ``/api/restore`` sit on a well-known port with no
auth: any web page the tech visits could POST to ``127.0.0.1:8765`` and write a
PBX (a DNS-rebinding write path). This closes it (DESIGN_PLAN 2.2, 14.6):

* a 32-byte launch **token**, generated per run and delivered once to the UI as
  a URL fragment, is required as ``X-CIX-Token`` on every ``/api`` call;
* the ``Host`` header must be loopback and any ``Origin`` must be loopback too,
  so a rebound attacker page (whose ``Origin`` is its own domain) is refused
  even if it somehow guessed the token; there is no CORS.

Static assets (the SPA itself) are served without a token so the browser can
load the page and read the fragment. The guard is **disabled when no token is
set** (``token=None``) — that is the mode the offline test harness and
``launcher.start_server`` run in, so nothing regresses.

The token is accepted as the ``X-CIX-Token`` header **or** as a ``Set-Cookie``
the ``/`` load plants (``cix_token``, ``SameSite=Strict``). The cookie means a
same-origin ``fetch`` authenticates with nothing added to the request — so the
existing SPA keeps working the moment auth is switched on — while a rebound
cross-site page is refused by both ``SameSite`` (the cookie is withheld) and
the Origin check (its Origin is not loopback).
"""


import secrets

COOKIE_NAME = "cix_token"


def _cookie_token(cookie_header: str) -> str | None:
    """Pull ``cix_token`` out of a raw ``Cookie:`` header (no http.cookies dep)."""
    if not cookie_header:
        return None
    for part in cookie_header.split(";"):
        name, _, value = part.strip().partition("=")
        if name == COOKIE_NAME:
            return value or None
    return None

_LOOPBACK_HOSTS = ("127.0.0.1", "localhost", "[::1]", "::1")


def generate_token() -> str:
    """A fresh URL-safe launch token (32 bytes of entropy)."""
    return secrets.token_urlsafe(32)


def _host_only(value: str) -> str:
    """Strip a scheme and port: ``http://127.0.0.1:8765`` -> ``127.0.0.1``."""
    v = (value or "").strip()
    if "://" in v:
        v = v.split("://", 1)[1]
    # keep a bracketed IPv6 literal intact, else drop a :port suffix
    if v.startswith("["):
        return v.split("]", 1)[0] + "]"
    return v.split(":", 1)[0] if ":" in v and v.count(":") == 1 else v


def is_loopback_host(value: str) -> bool:
    return _host_only(value) in _LOOPBACK_HOSTS


class LoopbackAuth:
    """Token + Origin/Host check. ``token=None`` disables it (dev/test)."""

    def __init__(self, token: str | None = None):
        self.token = token

    @property
    def enabled(self) -> bool:
        return bool(self.token)

    def check(self, *, headers, path: str):
        """Return ``(ok, status, message)`` for a request.

        ``headers`` is anything with ``.get(name)`` (an ``http.client`` message
        or a plain dict). Static (non-``/api``) paths always pass.
        """
        if not self.enabled:
            return True, 200, ""
        if not path.startswith("/api"):
            return True, 200, ""
        host = headers.get("Host")
        if host and not is_loopback_host(host):
            return False, 403, "non-loopback Host"
        origin = headers.get("Origin")
        if origin and not is_loopback_host(origin):
            return False, 403, "cross-origin request refused"
        token = (headers.get("X-CIX-Token") or headers.get("x-cix-token")
                 or _cookie_token(headers.get("Cookie") or ""))
        if not token or not secrets.compare_digest(str(token), str(self.token)):
            return False, 401, "missing or invalid launch token"
        return True, 200, ""

    def cookie_header(self) -> str | None:
        """The ``Set-Cookie`` value the ``/`` load plants, or ``None`` if off."""
        if not self.enabled:
            return None
        return (f"{COOKIE_NAME}={self.token}; Path=/; SameSite=Strict; "
                "HttpOnly")


__all__ = ["LoopbackAuth", "generate_token", "is_loopback_host", "COOKIE_NAME"]

# ===== server/router.py ============================================
"""A tiny method + path router with ``{param}`` segments.

The legacy webapp dispatched with a chain of ``if path == ...``; this replaces
it with a table so new routes (``/api/sites/{id}``) register declaratively and
the handler stays dumb. Matching is exact on the static segments; a single
``{name}`` segment captures one path component into ``params``. No regex, no
dependency, order-independent (longest static prefix wins on a tie so
``/api/jobs`` and ``/api/jobs/{id}`` coexist).
"""



class Router:
    def __init__(self):
        # method -> list of (segments, handler, has_param)
        self._routes: dict[str, list] = {}

    def add(self, method: str, pattern: str, handler) -> None:
        segs = _split(pattern)
        self._routes.setdefault(method.upper(), []).append(
            (segs, handler, any(_is_param(s) for s in segs)))

    def get(self, pattern, handler):
        self.add("GET", pattern, handler)

    def post(self, pattern, handler):
        self.add("POST", pattern, handler)

    def put(self, pattern, handler):
        self.add("PUT", pattern, handler)

    def delete(self, pattern, handler):
        self.add("DELETE", pattern, handler)

    def patch(self, pattern, handler):
        self.add("PATCH", pattern, handler)

    def match(self, method: str, path: str):
        """Return ``(handler, params)`` or ``None``.

        A static match wins over a parameterised one at the same length, so a
        literal route is never shadowed by a ``{param}`` sibling.
        """
        want = _split(path)
        candidates = []
        for segs, handler, has_param in self._routes.get(method.upper(), []):
            if len(segs) != len(want):
                continue
            params = {}
            ok = True
            for s, w in zip(segs, want):
                if _is_param(s):
                    params[s[1:-1]] = w
                elif s != w:
                    ok = False
                    break
            if ok:
                candidates.append((has_param, handler, params))
        if not candidates:
            return None
        # static (has_param False) sorts before parameterised
        candidates.sort(key=lambda c: c[0])
        _, handler, params = candidates[0]
        return handler, params

    def methods_for(self, path: str) -> list[str]:
        """Methods that *would* match ``path`` (for a 405 vs 404 decision)."""
        want = _split(path)
        out = []
        for method, routes in self._routes.items():
            for segs, _h, _p in routes:
                if len(segs) == len(want) and all(
                        _is_param(s) or s == w for s, w in zip(segs, want)):
                    out.append(method)
                    break
        return out


def _split(path: str) -> list[str]:
    return [p for p in path.split("?", 1)[0].split("/") if p != ""]


def _is_param(seg: str) -> bool:
    return len(seg) >= 2 and seg[0] == "{" and seg[-1] == "}"


__all__ = ["Router"]

# ===== server/jobs.py ==============================================
"""Long-op job runner — one thread per full read / restore / VM pull.

A job is a callable run off the request thread; it reports progress through a
``report(done, total, message)`` callback and its events fan out on the
:class:`~toshiba_cix.server.events.EventBus` as ``job.progress`` / ``job.done``
/ ``job.error`` so the UI's progress bars update over SSE (architecture.md 4.2,
DESIGN_PLAN 10.3). State is kept so ``GET /api/jobs/{id}`` can be polled when a
client missed the stream.

Pure stdlib (``threading``); the engine work the job does is injected as the
callable, so this module has no SNMP/serial knowledge and is unit-testable with
a trivial function.
"""


import threading
import time
import uuid


class Job:
    """One tracked unit of work and its live progress."""

    def __init__(self, job_id: str, kind: str):
        self.id = job_id
        self.kind = kind
        self.status = "pending"        # pending | running | done | error
        self.done = 0
        self.total = 0
        self.message = ""
        self.result = None
        self.error = None
        self.started = None
        self.finished = None

    def as_dict(self) -> dict:
        return {
            "id": self.id, "kind": self.kind, "status": self.status,
            "done": self.done, "total": self.total, "message": self.message,
            "error": self.error, "started": self.started,
            "finished": self.finished,
            # the result is included only once finished and only if JSON-ish
            "result": self.result if self.status == "done" else None,
        }


class JobManager:
    """Submit callables, track them, publish their progress to the bus."""

    def __init__(self, bus=None):
        self._bus = bus
        self._jobs: dict[str, Job] = {}
        self._lock = threading.Lock()

    def submit(self, kind: str, fn, *, join_for: float = 0.0) -> Job:
        """Run ``fn(report)`` in a daemon thread; return its :class:`Job` now.

        ``fn`` receives a ``report(done, total, message="")`` callback. Its
        return value becomes ``job.result``. ``join_for`` lets a caller/test
        wait up to N seconds for completion (0 = return immediately).
        """
        job = Job(uuid.uuid4().hex[:12], kind)
        with self._lock:
            self._jobs[job.id] = job

        def report(done, total=None, message=""):
            job.done = done
            if total is not None:
                job.total = total
            if message:
                job.message = message
            self._publish("job.progress", job)

        def run():
            job.status = "running"
            job.started = time.time()
            self._publish("job.progress", job)
            try:
                job.result = fn(report)
                job.status = "done"
                job.finished = time.time()
                self._publish("job.done", job)
            except Exception as exc:  # noqa: BLE001  — surface, never crash the daemon
                job.status = "error"
                job.error = f"{type(exc).__name__}: {exc}"
                job.finished = time.time()
                self._publish("job.error", job)

        t = threading.Thread(target=run, name=f"job-{job.id}", daemon=True)
        t.start()
        job._thread = t  # type: ignore[attr-defined]
        if join_for:
            t.join(timeout=join_for)
        return job

    def get(self, job_id: str) -> Job | None:
        with self._lock:
            return self._jobs.get(job_id)

    def list(self) -> list[dict]:
        with self._lock:
            jobs = list(self._jobs.values())
        jobs.sort(key=lambda j: (j.started or 0), reverse=True)
        return [j.as_dict() for j in jobs]

    def _publish(self, event: str, job: Job) -> None:
        if self._bus is not None:
            self._bus.publish(event, job.as_dict())


__all__ = ["Job", "JobManager"]

# ===== server/sessions.py ==========================================
"""Per-connected-device session state (the engine's working copy + mode).

A :class:`Session` is what the design's safety model hangs on (DESIGN_PLAN 5.5,
architecture.md 2): the last full read as the **working copy** (``doc``), the
**staged changeset** (``pending`` — nothing hits the wire on edit), the live
device **identity**, the arming **mode** with its idle expiry, and the session's
job ids. P0 lays the structure and the lifecycle hooks (mode changes and
identity updates publish to the SSE bus); the commit/simulate machinery that
fills it is P1/P2.

Pure stdlib and bus-injected; no SNMP here — a session is handed a device
descriptor, never a socket.
"""


import threading
import time
import uuid


# Arming modes. "armed" permits writes; it expires after an idle window
# (DESIGN_PLAN decision #6: 15 min local default, 10 remote, configurable).
MODE_DISARMED = "disarmed"
MODE_ARMED = "armed"
MODE_SIMULATE = "simulate"
_MODES = (MODE_DISARMED, MODE_ARMED, MODE_SIMULATE)

DEFAULT_ARM_MINUTES = 15
REMOTE_ARM_MINUTES = 10


class Session:
    def __init__(self, session_id: str, *, site=None, device=None,
                 transport=None, bus=None):
        self.id = session_id
        self.site = site
        self.device = device or {}
        self.transport = transport
        self.identity = None
        self.doc = {}                 # working copy: catalog_key -> program_view
        self.freshness = {}           # catalog_key -> read timestamp
        self.snapshot_meta = {}       # meta of the last read (scope, walk_error…)
        self.changeset = Changeset()  # staged edits (layer 2 — nothing on wire)
        self.last_applied = None      # ops of the last applied changeset (Undo)
        self.mode = MODE_DISARMED
        self.mode_expires = None
        self.jobs = []
        self.created = time.time()
        self._bus = bus
        self._client = None           # runtime SNMP client (never serialised)

    # -- identity ----------------------------------------------------------
    def set_identity(self, identity) -> None:
        self.identity = identity
        self._publish("session.identity",
                      {"session": self.id, "identity": identity})

    # -- runtime client (attached, not part of the data model) -------------
    def attach_client(self, client) -> None:
        """Hold the live SNMP client so a scoped re-read of one program works.

        A :class:`Session` is a data object (DESIGN_PLAN says it is handed a
        device descriptor, never a socket); the client is an attached runtime
        resource, kept off ``as_dict`` so nothing serialises a socket.
        """
        self._client = client

    @property
    def client(self):
        return self._client

    # -- working copy ------------------------------------------------------
    def ingest_views(self, program_views: dict) -> None:
        """Merge an enrich.py ``program_views`` dict into the working copy.

        Each ``<program_view>`` is stored under its ``catalog_key``; a later
        phase (``core`` then ``all``) replaces the earlier entry so the full
        walk supersedes the core one. Programs with data become browsable the
        moment their phase lands, which is what lets Stations open early."""
        now = time.time()
        for pv in (program_views or {}).get("programs", []):
            key = pv.get("catalog_key")
            if not key:
                continue
            self.doc[key] = pv
            self.freshness[key] = now

    def put_program_view(self, pv: dict) -> None:
        key = pv.get("catalog_key")
        if key:
            self.doc[key] = pv
            self.freshness[key] = time.time()

    def program_view(self, catalog_key: str):
        """The working-copy view for a catalog key, or ``None`` if unread."""
        return self.doc.get(catalog_key)

    def read_keys(self) -> list:
        """Catalog keys that returned data (what the nav shows as read)."""
        return sorted(self.doc.keys())

    # -- mode --------------------------------------------------------------
    def set_mode(self, mode: str, *, minutes: int | None = None) -> dict:
        if mode not in _MODES:
            raise ValueError(f"unknown mode {mode!r}")
        self.mode = mode
        if mode == MODE_ARMED:
            window = (REMOTE_ARM_MINUTES if self.transport in ("overlay", "agent")
                      else DEFAULT_ARM_MINUTES) if minutes is None else minutes
            self.mode_expires = time.time() + window * 60
        else:
            self.mode_expires = None
        state = self.mode_state()
        self._publish("session.mode", state)
        return state

    def mode_state(self) -> dict:
        expired = (self.mode == MODE_ARMED and self.mode_expires is not None
                   and time.time() >= self.mode_expires)
        if expired:
            # Lazily fall back to disarmed when the idle window passes.
            self.mode = MODE_DISARMED
            self.mode_expires = None
        return {"session": self.id, "mode": self.mode,
                "expires": self.mode_expires,
                "writable": self.mode == MODE_ARMED}

    def is_armed(self) -> bool:
        return self.mode_state()["mode"] == MODE_ARMED

    def as_dict(self) -> dict:
        return {"id": self.id, "site": self.site, "transport": self.transport,
                "identity": self.identity, "mode": self.mode_state()["mode"],
                "mode_expires": self.mode_expires,
                "pending": self.changeset.field_count(),
                "pending_rows": self.changeset.row_count(),
                "snapshot_meta": self.snapshot_meta,
                "programs_read": self.read_keys(),
                "programs_read_count": len(self.doc),
                "jobs": list(self.jobs)}

    def _publish(self, event, data):
        if self._bus is not None:
            self._bus.publish(event, data)


class SessionManager:
    def __init__(self, bus=None):
        self._bus = bus
        self._sessions: dict[str, Session] = {}
        self._lock = threading.Lock()

    def create(self, *, site=None, device=None, transport=None) -> Session:
        sid = uuid.uuid4().hex[:12]
        s = Session(sid, site=site, device=device, transport=transport,
                    bus=self._bus)
        with self._lock:
            self._sessions[sid] = s
        return s

    def get(self, session_id: str) -> Session | None:
        with self._lock:
            return self._sessions.get(session_id)

    def current(self) -> Session | None:
        """The most recently created session (the single-browser daemon's one)."""
        with self._lock:
            if not self._sessions:
                return None
            return max(self._sessions.values(), key=lambda s: s.created)

    def list(self) -> list[dict]:
        with self._lock:
            return [s.as_dict() for s in self._sessions.values()]

    def drop(self, session_id: str) -> bool:
        with self._lock:
            return self._sessions.pop(session_id, None) is not None


__all__ = ["Session", "SessionManager", "MODE_DISARMED", "MODE_ARMED",
           "MODE_SIMULATE"]

# ===== server/schema.py ============================================
"""Load the generated ``ui_schema.json`` and serve it at ``GET /api/schema``.

The schema is the one static UI data file (DESIGN_PLAN 2.1): the engine and the
React store both read it, so they agree on every label, enum, range, archetype
and menu. Loading reuses :func:`toshiba_cix.catalog._load_data_text`, so it
resolves identically across every packaging — the base64 embed in the
single-file amalgam, the PyInstaller ``_MEIPASS`` bundle and the packaged
``toshiba_cix/data/`` dir of a dev checkout — and degrades to a clear error if
a build forgot to bundle it rather than crashing at import.
"""


import json


UI_SCHEMA_FILENAME = "ui_schema.json"
_CACHE: dict | None = None
_TEXT_CACHE: str | None = None


def load_ui_schema_text() -> str:
    global _TEXT_CACHE
    if _TEXT_CACHE is not None:
        return _TEXT_CACHE
    text = _load_data_text(UI_SCHEMA_FILENAME, "EMBEDDED_UI_SCHEMA_JSON")
    if text is None:
        raise FileNotFoundError(
            "ui_schema.json not found — run: python3 tools/build_ui_schema.py")
    _TEXT_CACHE = text
    return text


def load_ui_schema(*, cache: bool = True) -> dict:
    global _CACHE
    if cache and _CACHE is not None:
        return _CACHE
    data = json.loads(load_ui_schema_text())
    if cache:
        _CACHE = data
    return data


def schema_summary() -> dict:
    """Small identity for ``/api/health`` (version + counts), schema-missing safe."""
    try:
        s = load_ui_schema()
    except Exception:  # noqa: BLE001
        return {"schema_available": False}
    return {"schema_available": True,
            "schema_version": s.get("schema_version"),
            "catalog_version": s.get("catalog_version"),
            "counts": s.get("counts", {})}


__all__ = ["load_ui_schema", "load_ui_schema_text", "schema_summary",
           "UI_SCHEMA_FILENAME"]
EMBEDDED_UI_SCHEMA_JSON = base64.b64decode("").decode("utf-8")  # bundled generated UI schema

# ===== server/http.py ==============================================
"""The HTTP request handler: auth, routing, JSON/bytes/SSE responses.

``build_handler(ctx)`` returns a :class:`http.server.BaseHTTPRequestHandler`
subclass bound to a :class:`~toshiba_cix.server.app.ServerContext`. It keeps the
old webapp's response semantics (so nothing regresses) and adds:

* the loopback token + Origin/Host gate on every ``/api`` call (``ctx.auth``);
* table-driven dispatch (``ctx.router``) with ``{param}`` capture;
* the ``text/event-stream`` server for ``GET /api/events`` (``ctx.bus``);
* a ``Set-Cookie`` planted on the ``/`` load so the same-origin SPA
  authenticates with nothing added to its requests.

Route functions take ``(ctx, req)`` and use the :class:`Request` facade's
``send_json`` / ``send_bytes`` / ``body`` helpers, so they can live in
``webapp.py`` (preserving the monkeypatch seam the tests rely on) while this
module owns the socket.
"""


import json
import logging
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse


log = logging.getLogger("toshiba_cix.server")

_SSE_HEARTBEAT_SECS = 20.0


class Request:
    """Per-request facade handed to a route function."""

    def __init__(self, handler: BaseHTTPRequestHandler, params: dict):
        self.handler = handler
        self.params = params or {}
        parsed = urlparse(handler.path)
        self.path = parsed.path
        self.query = {k: v[-1] for k, v in parse_qs(parsed.query).items()}
        self._body = _UNSET

    @property
    def headers(self):
        return self.handler.headers

    def body(self) -> dict:
        """Parsed JSON request body ({} if empty). Raises ``ValueError`` on bad JSON."""
        if self._body is _UNSET:
            length = int(self.headers.get("Content-Length") or 0)
            if not length:
                self._body = {}
            else:
                raw = self.handler.rfile.read(length)
                self._body = json.loads(raw.decode("utf-8")) if raw else {}
        return self._body

    # -- responses ---------------------------------------------------------
    def send_json(self, obj, status: int = 200) -> None:
        body = json.dumps(obj, default=str).encode("utf-8")
        self._start(status, "application/json", len(body))
        self.handler.wfile.write(body)

    def send_text(self, text: str, status: int = 200,
                  content_type: str = "text/plain; charset=utf-8") -> None:
        body = text.encode("utf-8")
        self._start(status, content_type, len(body))
        self.handler.wfile.write(body)

    def send_bytes(self, body: bytes, content_type: str, status: int = 200,
                   filename: str | None = None, extra_headers=None) -> None:
        self._start(status, content_type, len(body),
                    disposition=(f'attachment; filename="{filename}"'
                                 if filename else None),
                    extra_headers=extra_headers)
        self.handler.wfile.write(body)

    def _start(self, status, content_type, length, disposition=None,
               extra_headers=None):
        h = self.handler
        h.send_response(status)
        h.send_header("Content-Type", content_type)
        h.send_header("Content-Length", str(length))
        if disposition:
            h.send_header("Content-Disposition", disposition)
        for k, v in (extra_headers or {}).items():
            h.send_header(k, v)
        h.end_headers()


_UNSET = object()


def build_handler(ctx):
    """Return a request-handler class bound to ``ctx`` (router/auth/bus/...)."""

    class Handler(BaseHTTPRequestHandler):
        # HTTP/1.0 (the default): a response closes its connection, which keeps
        # the SSE stream simple (no chunked framing) and matches the old
        # handler's semantics so nothing regresses.
        server_version = f"Switchroom/{getattr(ctx, 'version', '0')}"

        def log_message(self, fmt, *args):  # noqa: N802  — quiet; route to logger
            log.debug("%s - %s", self.address_string(), fmt % args)

        # -- method entry points ------------------------------------------
        def do_GET(self):  # noqa: N802
            if not self._guard():
                return
            if urlparse(self.path).path == "/api/events":
                self._serve_sse()
                return
            self._dispatch("GET")

        def do_POST(self):  # noqa: N802
            if self._guard():
                self._dispatch("POST")

        def do_PUT(self):  # noqa: N802
            if self._guard():
                self._dispatch("PUT")

        def do_PATCH(self):  # noqa: N802
            if self._guard():
                self._dispatch("PATCH")

        def do_DELETE(self):  # noqa: N802
            if self._guard():
                self._dispatch("DELETE")

        # -- auth ----------------------------------------------------------
        def _guard(self) -> bool:
            ok, status, message = ctx.auth.check(
                headers=self.headers, path=urlparse(self.path).path)
            if ok:
                return True
            body = json.dumps({"ok": False, "error": message}).encode()
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return False

        # -- dispatch ------------------------------------------------------
        def _dispatch(self, method: str):
            path = urlparse(self.path).path
            match = ctx.router.match(method, path)
            if match is None:
                allowed = ctx.router.methods_for(path)
                if allowed:
                    self._error(405, f"method not allowed (try {','.join(sorted(allowed))})")
                else:
                    self._error(404, "not found")
                return
            handler, params = match
            req = Request(self, params)
            try:
                handler(ctx, req)
            except (ValueError, json.JSONDecodeError) as exc:
                self._safe_json({"ok": False, "error": f"bad request: {exc}"}, 400)
            except BrokenPipeError:  # pragma: no cover — client went away
                pass
            except Exception as exc:  # noqa: BLE001
                log.exception("handler error on %s %s", method, path)
                self._safe_json(
                    {"ok": False, "error": f"{type(exc).__name__}: {exc}"}, 500)

        # -- SSE -----------------------------------------------------------
        def _serve_sse(self):
            sub = ctx.bus.subscribe()
            try:
                self.send_response(200)
                self.send_header("Content-Type", "text/event-stream")
                self.send_header("Cache-Control", "no-cache")
                self.send_header("Connection", "keep-alive")
                self.end_headers()
                self.wfile.write(b": connected\n\n")
                self.wfile.flush()
                while not sub.closed:
                    frame = sub.get(timeout=_SSE_HEARTBEAT_SECS)
                    payload = frame if frame is not None else (HEARTBEAT + "\n\n")
                    self.wfile.write(payload.encode("utf-8"))
                    self.wfile.flush()
            except (BrokenPipeError, ConnectionResetError, OSError):
                pass
            finally:
                sub.close()

        # -- error helpers -------------------------------------------------
        def _error(self, status, message):
            self._safe_json({"ok": False, "error": message}, status)

        def _safe_json(self, obj, status):
            try:
                body = json.dumps(obj, default=str).encode()
                self.send_response(status)
                self.send_header("Content-Type", "application/json")
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)
            except (BrokenPipeError, ConnectionResetError, OSError):  # pragma: no cover
                pass

    return Handler


__all__ = ["build_handler", "Request", "ThreadingHTTPServer"]

# ===== server/app.py ===============================================
"""Server assembly: the context, the P0 core routes, and the launch.

``ServerContext`` is the one object the handler closes over — router, auth
guard, SSE bus, job runner, session registry and the on-disk store (AppDirs +
site book + journal). ``register_core_routes`` adds the routes P0 owns
(``/api/schema``, ``/api/sites``, ``/api/jobs``, ``/api/journal`` and the
session/mode trio that drives the SSE channel); the legacy JSON routes are
registered by ``webapp`` so their handler semantics — and the test monkeypatch
seam — are untouched.

``run_server`` binds an OS-chosen loopback port (never a fixed one, so a second
instance can't collide), ``serve`` adds the app-mode browser open and the
auto-exit-after-last-client rule. All stdlib.
"""


import logging
import os
import socket
import subprocess
import sys
import threading
from urllib.parse import urlparse


log = logging.getLogger("toshiba_cix.server")

AUTOEXIT_GRACE_SECS = 20.0


class ServerContext:
    """Everything a request handler needs, assembled once per server."""

    def __init__(self, *, token=None, appdirs: AppDirs | None = None,
                 version: str = __version__):
        self.version = version
        self.router = Router()
        self.auth = LoopbackAuth(token)
        self.bus = EventBus()
        self.jobs = JobManager(self.bus)
        self.sessions = SessionManager(self.bus)
        self.appdirs = appdirs
        self._sitebook = None
        self._journal = None
        self._snapshots = None

    # -- lazy store accessors (nothing is created until a route needs it) --
    def sitebook(self):
        if self.appdirs is None:
            return SiteBook(os.path.join(store_root(), "sites.json"))
        if self._sitebook is None:
            self.appdirs.ensure()
            self._sitebook = sitebook_from_root(self.appdirs)
        return self._sitebook

    def journal(self):
        if self._journal is None:
            root = self.appdirs or AppDirs(store_root())
            root.ensure()
            self._journal = journal_from_root(root)
        return self._journal

    def snapshots(self):
        if self._snapshots is None:
            root = self.appdirs or AppDirs(store_root())
            root.ensure()
            cat = None
            try:
                cat = load_catalog()
            except Exception:  # noqa: BLE001 — the store works without it
                cat = None
            self._snapshots = SnapshotStore(root.root, catalog=cat)
        return self._snapshots


# --------------------------------------------------------------------------
# P0 core routes
# --------------------------------------------------------------------------
def register_core_routes(ctx: ServerContext) -> None:
    ctx.router.get("/api/schema", _schema)
    ctx.router.get("/api/sites", _sites_list)
    ctx.router.post("/api/sites", _sites_upsert)
    ctx.router.put("/api/sites/{id}", _sites_put)
    ctx.router.delete("/api/sites/{id}", _sites_delete)
    ctx.router.get("/api/jobs", _jobs_list)
    ctx.router.get("/api/jobs/{id}", _jobs_get)
    ctx.router.get("/api/journal", _journal_list)
    ctx.router.post("/api/sessions", _sessions_create)
    ctx.router.get("/api/sessions", _sessions_list)
    ctx.router.post("/api/sessions/{id}/mode", _session_mode)


def _schema(ctx, req):
    # Served as raw text (it is already JSON) so the big file is not re-encoded.
    req.send_text(load_ui_schema_text(), content_type="application/json")


def _sites_list(ctx, req):
    req.send_json({"ok": True, "sites": ctx.sitebook().load()})


def _sites_upsert(ctx, req):
    body = req.body()
    if not isinstance(body, dict) or not (body.get("name") or body.get("id")):
        req.send_json({"ok": False, "error": "a site needs a name or id"}, 400)
        return
    site = ctx.sitebook().upsert(body)
    req.send_json({"ok": True, "site": site})


def _sites_put(ctx, req):
    body = dict(req.body() or {})
    body["id"] = req.params["id"]
    req.send_json({"ok": True, "site": ctx.sitebook().upsert(body)})


def _sites_delete(ctx, req):
    removed = ctx.sitebook().delete(req.params["id"])
    req.send_json({"ok": removed, "deleted": req.params["id"]},
                  200 if removed else 404)


def _jobs_list(ctx, req):
    req.send_json({"ok": True, "jobs": ctx.jobs.list()})


def _jobs_get(ctx, req):
    job = ctx.jobs.get(req.params["id"])
    if job is None:
        req.send_json({"ok": False, "error": "no such job"}, 404)
        return
    req.send_json({"ok": True, "job": job.as_dict()})


def _journal_list(ctx, req):
    limit = int(req.query.get("limit") or 100)
    req.send_json({"ok": True, "commits": ctx.journal().list_commits(limit)})


def _sessions_create(ctx, req):
    body = req.body() or {}
    s = ctx.sessions.create(site=body.get("site"), device=body.get("device"),
                            transport=body.get("transport"))
    req.send_json({"ok": True, "session": s.as_dict()})


def _sessions_list(ctx, req):
    req.send_json({"ok": True, "sessions": ctx.sessions.list()})


def _session_mode(ctx, req):
    s = ctx.sessions.get(req.params["id"])
    if s is None:
        req.send_json({"ok": False, "error": "no such session"}, 404)
        return
    body = req.body() or {}
    mode = body.get("mode")
    try:
        state = s.set_mode(mode, minutes=body.get("minutes"))
    except ValueError as exc:
        req.send_json({"ok": False, "error": str(exc)}, 400)
        return
    req.send_json({"ok": True, "mode": state})


# --------------------------------------------------------------------------
# launch
# --------------------------------------------------------------------------
def pick_free_port(host: str, preferred: int) -> int:
    """``preferred`` if free, else the next free (up to +20); 0 lets the OS pick."""
    if preferred == 0:
        return 0
    for port in range(preferred, preferred + 21):
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        try:
            s.bind((host, port))
            return port
        except OSError:
            continue
        finally:
            s.close()
    return preferred


def make_server(ctx: ServerContext, host: str = "127.0.0.1", port: int = 0):
    """Bind the server (OS-chosen port by default) and return ``(httpd, url)``."""
    httpd = ThreadingHTTPServer((host, pick_free_port(host, port)),
                                build_handler(ctx))
    actual = httpd.server_address[1]
    ctx.host, ctx.port = host, actual
    return httpd, f"http://{host}:{actual}"


def _open_app_window(url: str) -> None:
    """Open the UI chromeless in app mode; fall back to a normal browser tab.

    Tries Edge/Chrome/Chromium/Brave ``--app=`` (a dedicated window with its own
    taskbar entry) before the stdlib ``webbrowser``. Best-effort and silent.
    """
    candidates = {
        "win32": [["cmd", "/c", "start", "msedge", f"--app={url}"],
                  ["cmd", "/c", "start", "chrome", f"--app={url}"]],
        "darwin": [["open", "-na", "Google Chrome", "--args", f"--app={url}"],
                   ["open", "-na", "Microsoft Edge", "--args", f"--app={url}"]],
    }.get(sys.platform, [[b, f"--app={url}"] for b in
                         ("google-chrome", "chromium", "chromium-browser",
                          "brave-browser", "microsoft-edge")])
    for cmd in candidates:
        try:
            subprocess.Popen(cmd, stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL)
            return
        except (OSError, ValueError):
            continue
    try:
        import webbrowser
        webbrowser.open(url)
    except Exception:  # noqa: BLE001
        pass


def _install_autoexit(httpd, ctx: ServerContext, grace: float) -> None:
    """Shut the daemon down ``grace`` seconds after the last SSE client leaves.

    A new client within the grace window cancels the pending exit, so a browser
    reload does not kill the server. Agent/bridge mode disables this.
    """
    state = {"timer": None}

    def on_count(count: int):
        t = state["timer"]
        if count > 0:
            if t is not None:
                t.cancel()
                state["timer"] = None
            return
        if t is None:
            timer = threading.Timer(grace, _shutdown)
            timer.daemon = True
            state["timer"] = timer
            timer.start()

    def _shutdown():
        if ctx.bus.subscriber_count() == 0:
            log.info("no clients for %ss — exiting", grace)
            threading.Thread(target=httpd.shutdown, daemon=True).start()

    ctx.bus.on_count_change(on_count)


def run_server(ctx: ServerContext, host: str = "127.0.0.1", port: int = 0, *,
               open_browser: bool = True, autoexit: bool = True,
               block: bool = True, on_ready=None):
    """Create, optionally open + auto-exit, and serve. Returns ``(httpd, url)``.

    ``on_ready(url)`` is called once the server is bound and about to serve.
    With ``block=False`` it serves in a daemon thread and returns at once
    (tests / embedders); call ``httpd.shutdown()`` to stop it.
    """
    httpd, base = make_server(ctx, host, port)
    url = base + (f"/#token={ctx.auth.token}" if ctx.auth.enabled else "/")
    if autoexit:
        _install_autoexit(httpd, ctx, AUTOEXIT_GRACE_SECS)
    if open_browser:
        _open_app_window(url)
    if on_ready:
        on_ready(url)
    if not block:
        threading.Thread(target=httpd.serve_forever, daemon=True).start()
        return httpd, url
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
    return httpd, url


__all__ = ["ServerContext", "register_core_routes", "make_server",
           "run_server", "pick_free_port"]

# ===== webapp.py ===================================================
"""Legacy JSON routes + launch for the Toshiba CIX Manager / Switchroom.

The HTTP *plumbing* now lives in :mod:`toshiba_cix.server` (router, loopback
token + Origin/Host guard, OS-chosen port, sessions, jobs, SSE ``/api/events``,
static UI). This module keeps the **route handlers** that read/view/diff/
restore a CIX over SNMP and wires them, plus the P0 core routes, onto a
:class:`~toshiba_cix.server.app.ServerContext`.

They stay here (as module-level ``route_*`` functions, not methods) for two
reasons: their behaviour must not regress, and the offline tests drive them by
monkeypatching module globals (``SnmpV1``, ``DISC``, ``check_for_update`` …) —
which only works because every handler resolves those names from *this*
module's namespace at call time.

Served endpoints are unchanged:
    GET  /               the single-page UI (``webui.html``)
    GET  /api/health     {ok, version, writes_enabled, schema}
    GET  /api/discover · /api/catalog · /api/update
    POST /api/connect · /api/read · /api/backup · /api/save
    POST /api/catalog-backup · /api/view · /api/diff · /api/restore · /api/update
plus the P0 additions: GET /api/schema, /api/sites, /api/jobs, /api/journal,
the session/mode trio and SSE /api/events (see :mod:`toshiba_cix.server`).

All SNMP reads are read-only (GET/GETNEXT); writes go through
:mod:`toshiba_cix.write` with explicit confirmation and GET-verify.
"""


import io
import json
import logging
import os
import sys
import zipfile
from datetime import datetime, timezone

# Non-aliased so the single-file build (which flattens the package into one
# module and strips intra-package imports) resolves these as globals, and so a
# test can monkeypatch them on this module.
# Bare names (no import aliases): the single-file build flattens the package and
# strips intra-package imports, so an `import X as Y` alias would vanish there.
# P2 write path: staged changeset -> three-way review -> gated apply / Simulate.
# Bare names so the single-file build resolves them after it flattens the package.
# P4 polish: config linter + wizard planners (pure; preview only, no apply).
# Bare names (no `as` alias): the single-file build strips the import line and
# resolves these as flattened globals, so they must match the source names.
# ``writes_enabled`` (a function) is imported, NOT ``WRITES_ENABLED`` (a value):
# importing the value would freeze a snapshot at import time, so a runtime toggle
# (a test, a future UI switch) would never be seen. Every call site reads the
# live master switch via ``writes_enabled()`` at request time.
# Voicemail leg (DESIGN_PLAN §8). Bare names so the single-file build resolves
# them as globals after it flattens the package.

log = logging.getLogger("toshiba_cix.webapp")

_HTML_CACHE: str | None = None


def load_html() -> str:
    """Return the UI HTML, wherever this is running from.

    Order: the base64-embedded copy (the ``toshiba_cix_manager.py`` standalone)
    → a PyInstaller bundle (``sys._MEIPASS``) → the sibling ``webui.html`` (from
    the package / a dev checkout).
    """
    global _HTML_CACHE
    if _HTML_CACHE is not None:
        return _HTML_CACHE
    embedded = globals().get("EMBEDDED_WEBUI_HTML")
    if embedded:
        _HTML_CACHE = embedded
        return _HTML_CACHE
    candidates = []
    meipass = getattr(sys, "_MEIPASS", None)   # set when frozen by PyInstaller
    if meipass:
        candidates.append(os.path.join(meipass, "toshiba_cix", "webui.html"))
        candidates.append(os.path.join(meipass, "webui.html"))
    candidates.append(
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "webui.html"))
    for path in candidates:
        if os.path.exists(path):
            with open(path, encoding="utf-8") as fh:
                _HTML_CACHE = fh.read()
            return _HTML_CACHE
    raise FileNotFoundError("webui.html not found (looked in: "
                            + ", ".join(candidates) + ")")


def _reader(params: dict, *, keep_raw_walk: bool) -> CIXReader:
    ip = (params.get("ip") or "").strip()
    if not ip:
        raise ValueError("missing CIX IP address")
    community = (params.get("community") or "communityName").strip() or "communityName"
    port = int(params.get("port") or 161)
    timeout = float(params.get("timeout") or 3.0)
    retries = int(params.get("retries") or 1)
    scope = params.get("scope") or "core"
    strategy = "serial" if params.get("serial") else "bulk"
    width = int(params.get("width") or 10)
    client = SnmpV1(ip, community, port=port, timeout=timeout, retries=retries)
    return CIXReader(client, scope=scope, strategy=strategy, width=width,
                     keep_raw_walk=keep_raw_walk)


# --------------------------------------------------------------------------
# static UI
# --------------------------------------------------------------------------
def route_index(ctx, req):
    html = load_html().encode("utf-8")
    extra = {}
    cookie = ctx.auth.cookie_header()
    if cookie:
        extra["Set-Cookie"] = cookie
    req.send_bytes(html, "text/html; charset=utf-8", extra_headers=extra)


# --------------------------------------------------------------------------
# simple GETs
# --------------------------------------------------------------------------
def route_health(ctx, req):
    req.send_json({"ok": True, "version": __version__,
                   "writes_enabled": writes_enabled(),
                   "schema": schema_summary()})


def route_discover(ctx, req):
    try:
        result = DISC.discover_cix()
        result["ok"] = True
        req.send_json(result)
    except Exception as exc:  # noqa: BLE001
        log.exception("discover failed")
        req.send_json({"ok": False, "error": str(exc), "candidates": []})


def route_catalog(ctx, req):
    try:
        cat = load_catalog()
    except Exception as exc:  # noqa: BLE001
        req.send_json({"ok": False, "error": str(exc)}, 500)
        return
    out = {"ok": True, "writes_enabled": writes_enabled()}
    out.update(cat.summary())
    req.send_json(out)


def route_update_check(ctx, req):
    try:
        req.send_json(check_for_update())
    except Exception as exc:  # noqa: BLE001  — check must never 500
        req.send_json({"ok": False, "error": f"{type(exc).__name__}: {exc}"})


# --------------------------------------------------------------------------
# connect / read / backup
# --------------------------------------------------------------------------
def route_connect(ctx, req):
    try:
        reader = _reader(req.body(), keep_raw_walk=False)
    except ValueError as exc:
        req.send_json({"ok": False, "error": str(exc)}, 400)
        return
    client = reader.client
    try:
        vbs = client.get([DISC.SOFTWARE_ID_OID, DISC.CHASSIS_MAC_OID])
    except SnmpError as exc:
        req.send_json({"ok": False, "error": str(exc)})
        return
    by_oid = {vb.oid: vb.value for vb in vbs}
    sw = by_oid.get(DISC.SOFTWARE_ID_OID)
    if sw is None or sw.is_missing or sw.kind != "octet" or not sw.raw:
        req.send_json({"ok": False,
                       "error": "no CIX software-id reply (wrong community, "
                                "not a CIX, or UDP 161 blocked)"})
        return
    out = {"ok": True, "software_id": D.decode_value(sw)}
    mac = by_oid.get(DISC.CHASSIS_MAC_OID)
    if mac is not None and mac.kind == "octet" and mac.raw:
        out["chassis_mac"] = D.decode_value(mac, as_mac=True)
    req.send_json(out)


def route_read(ctx, req):
    try:
        reader = _reader(req.body(), keep_raw_walk=True)
    except ValueError as exc:
        req.send_json({"ok": False, "error": str(exc)}, 400)
        return
    try:
        doc = reader.read()
    except SnmpError as exc:
        req.send_json({"ok": False, "error": str(exc)})
        return
    except Exception as exc:  # noqa: BLE001
        log.exception("read failed")
        req.send_json({"ok": False, "error": f"{type(exc).__name__}: {exc}"})
        return
    if not doc.get("stations") and not doc["system"].get("software_id") \
            and doc["device"]["oids_read"] == 0:
        req.send_json({"ok": False,
                       "error": "no data returned — wrong community, not a "
                                "CIX, or UDP 161 blocked"})
        return
    req.send_json({"ok": True, "doc": doc, "report": render_report(doc)})


def route_backup_zip(ctx, req):
    doc = req.body().get("doc")
    if not isinstance(doc, dict):
        req.send_json({"ok": False, "error": "missing doc"}, 400)
        return
    try:
        body = build_backup_zip(doc)
    except Exception as exc:  # noqa: BLE001
        req.send_json({"ok": False, "error": str(exc)}, 500)
        return
    ip = (doc.get("device") or {}).get("ip") or "cix"
    ts = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
    fname = f"toshiba-cix-{str(ip).replace('/', '_')}-{ts}-backup.zip"
    req.send_bytes(body, "application/zip", filename=fname)


def route_save(ctx, req):
    """Plan a station edit and PREVIEW it. This route is **preview-only** and
    NEVER writes.

    The single gated live-write path is the armed Review & Write session flow
    (``POST /api/sessions/{id}/apply`` — arm programming mode, confirm, and type
    the site name). The legacy direct write from this route has been retired: a
    ``confirm: true`` is refused with 409 and points the caller at that flow.
    Preview never touches the network.
    """
    params = req.body()
    station = params.get("station") or {}
    changes = params.get("changes") or {}
    confirm = bool(params.get("confirm"))
    writer = CIXWriter()           # no client: planning is pure, sends nothing
    try:
        ops = writer.plan_station_update(station, changes)
    except Exception as exc:  # noqa: BLE001
        req.send_json({"ok": False, "error": str(exc)}, 400)
        return

    planned_ops = [op.as_dict() for op in ops]
    if confirm:
        # The old direct-write path is gone. Direct the caller to the one gated
        # write path; return the plan too so nothing useful is lost.
        req.send_json({
            "ok": False, "mode": "preview", "writes_enabled": writes_enabled(),
            "error": ("/api/save is preview-only and no longer writes. Apply "
                      "changes through the gated Review & Write flow "
                      "(POST /api/sessions/{id}/apply): arm programming mode, "
                      "confirm, and type the site name."),
            "planned_ops": planned_ops,
        }, 409)
        return

    req.send_json({
        "ok": True, "mode": "preview", "writes_enabled": writes_enabled(),
        "message": ("Preview only — nothing was sent. Apply changes through the "
                    "Review & Write flow: arm programming mode, confirm, and "
                    "type the site name."),
        "planned_ops": planned_ops,
    })


# --------------------------------------------------------------------------
# catalog-driven backup / view / diff / restore
# --------------------------------------------------------------------------
def route_catalog_backup(ctx, req):
    try:
        reader = _reader(req.body(), keep_raw_walk=False)
    except ValueError as exc:
        req.send_json({"ok": False, "error": str(exc)}, 400)
        return
    params = req.body()
    programs = params.get("programs") or None
    site = params.get("site")
    try:
        cat = load_catalog()
        doc = backup(reader.client, cat, site=site, programs=programs,
                     width=reader.width)
    except SnmpError as exc:
        req.send_json({"ok": False, "error": str(exc)})
        return
    except Exception as exc:  # noqa: BLE001
        log.exception("catalog backup failed")
        req.send_json({"ok": False, "error": f"{type(exc).__name__}: {exc}"})
        return
    if doc["meta"].get("oids_read", 0) == 0:
        req.send_json({"ok": False,
                       "error": "no data returned — wrong community, not a "
                                "CIX, or UDP 161 blocked"})
        return
    req.send_json({"ok": True, "backup": doc,
                   "report": render_backup_text(doc, catalog=cat),
                   "program_views": program_views_from_backup(doc, cat)})


def route_view(ctx, req):
    params = req.body()
    doc = params.get("backup")
    if not isinstance(doc, dict):
        req.send_json({"ok": False, "error": "missing backup"}, 400)
        return
    try:
        cat = load_catalog()
        report = render_backup_text(doc, catalog=cat,
                                    program=params.get("program"),
                                    max_rows=params.get("max_rows"))
    except Exception as exc:  # noqa: BLE001
        req.send_json({"ok": False, "error": str(exc)}, 500)
        return
    req.send_json({"ok": True, "report": report, "meta": doc.get("meta", {}),
                   "programs": sorted(doc.get("programs", {}).keys()),
                   "program_views": program_views_from_backup(doc, cat)})


def route_diff(ctx, req):
    params = req.body()
    a, b = params.get("a"), params.get("b")
    if not isinstance(a, dict) or not isinstance(b, dict):
        req.send_json({"ok": False, "error": "need two backups (a, b)"}, 400)
        return
    try:
        cat = load_catalog()
        d = diff_backups(a, b, catalog=cat, ignore_readonly=not params.get("all"))
    except Exception as exc:  # noqa: BLE001
        req.send_json({"ok": False, "error": str(exc)}, 500)
        return
    req.send_json({"ok": True, "diff": d, "report": render_diff_text(d)})


def route_restore(ctx, req):
    """Plan a restore and PREVIEW it, or with ``confirm: true`` write + verify.

    Gated by WRITES_ENABLED + confirm (reusing CIXWriter). Read-only fields are
    never sent; applies to RAM (reboot persistence unproven)."""
    params = req.body()
    doc = params.get("backup")
    if not isinstance(doc, dict):
        req.send_json({"ok": False, "error": "missing backup"}, 400)
        return
    confirm = bool(params.get("confirm"))
    programs = params.get("programs") or None
    from_diff = params.get("from_diff") or None
    try:
        cat = load_catalog()
    except Exception as exc:  # noqa: BLE001
        req.send_json({"ok": False, "error": str(exc)}, 500)
        return

    client = None
    if confirm:
        try:
            reader = _reader(params, keep_raw_walk=False)
        except ValueError as exc:
            req.send_json({"ok": False, "error": str(exc)}, 400)
            return
        client = reader.client
    try:
        result = restore(client, doc, cat, confirm=confirm, programs=programs,
                         from_diff=from_diff)
    except (WriteError, SnmpError) as exc:
        req.send_json({"ok": False, "mode": "write", "error": str(exc)})
        return
    except Exception as exc:  # noqa: BLE001
        log.exception("restore failed")
        req.send_json({"ok": False, "error": f"{type(exc).__name__}: {exc}"})
        return
    req.send_json(result)


def route_update_apply(ctx, req):
    """POST /api/update — download + install the latest release. Requires an
    explicit ``{"confirm": true}``; a plain POST only reports the plan."""
    if not bool(req.body().get("confirm")):
        req.send_json({"ok": False, "error": "apply requires an explicit confirm",
                       "plan": plan_update()}, 400)
        return
    try:
        result = apply_update(confirm=True)
    except Exception as exc:  # noqa: BLE001
        log.exception("update apply failed")
        req.send_json({"ok": False, "error": f"{type(exc).__name__}: {exc}"})
        return
    req.send_json(result)


# --------------------------------------------------------------------------
# P1 browse: session working copy + snapshot-on-connect + per-program reads
# --------------------------------------------------------------------------
def route_snapshot_start(ctx, req):
    """POST /api/snapshot — connect a CIX and start the core→all snapshot job.

    Creates a session, attaches the live (read-only) SNMP client, and submits a
    background job that reads core programs first (stations/trunks open fast)
    then the rest, populating the session working copy as each phase lands and
    saving the finished snapshot for cold start. Returns the session + job ids;
    progress streams on SSE ``/api/events`` (``job.progress`` / ``session.*``).
    """
    params = req.body()
    try:
        reader = _reader(params, keep_raw_walk=False)
    except ValueError as exc:
        req.send_json({"ok": False, "error": str(exc)}, 400)
        return
    try:
        cat = load_catalog()
    except Exception as exc:  # noqa: BLE001
        req.send_json({"ok": False, "error": f"catalog unavailable: {exc}"}, 500)
        return

    client = reader.client
    site = params.get("site")
    site_id = params.get("site_id") or slugify_id(site or getattr(client, "host", "cix"))
    transport = "overlay" if params.get("reach") == "remote" else "direct"
    session = ctx.sessions.create(site=site,
                                  device={"ip": getattr(client, "host", None)},
                                  transport=transport)
    session.attach_client(client)

    def job(report):
        def on_phase(views, phase):
            session.ingest_views(views)
            ctx.bus.publish("session.programs",
                            {"session": session.id, "phase": phase,
                             "read": len(session.doc)})

        snap = read_snapshot(client, cat, report=report, on_phase=on_phase,
                             site=site, transport=transport, width=reader.width)
        ident = snap["identity"]
        session.set_identity({"software_id": ident.get("swid"),
                              "chassis_mac": ident.get("chassis_mac")})
        session.snapshot_meta = snap["meta"]
        header = None
        try:
            # Persist the v2 backup doc (dedupes on content hash); the store
            # prunes auto snapshots so the folder does not grow without bound.
            store = ctx.snapshots()
            header = store.put(site_id, snap["backup"], kind="snapshot",
                               transport=transport)
            store.prune(site_id)
        except Exception as exc:  # noqa: BLE001 — a save failure must not fail the read
            log.warning("snapshot save failed: %s", exc)
        return {"session": session.id, "site_id": site_id, "saved": header,
                "identity": ident, "meta": snap["meta"],
                "stats": snap["program_views"].get("stats")}

    j = ctx.jobs.submit("snapshot", job)
    session.jobs.append(j.id)
    req.send_json({"ok": True, "session": session.id, "site_id": site_id,
                   "job": j.id})


def _session_or_404(ctx, req):
    s = ctx.sessions.get(req.params["id"])
    if s is None:
        req.send_json({"ok": False, "error": "no such session"}, 404)
    return s


def route_session_get(ctx, req):
    s = _session_or_404(ctx, req)
    if s is not None:
        req.send_json({"ok": True, "session": s.as_dict()})


def route_session_snapshot(ctx, req):
    """GET /api/sessions/{id}/snapshot — the working-copy program index.

    A light view the nav uses to grey unread programs and show row counts: the
    identity, the snapshot meta, and one line per program that returned data.
    """
    s = _session_or_404(ctx, req)
    if s is None:
        return
    programs = [{"catalog_key": pv.get("catalog_key"),
                 "program_number": pv.get("program_number"),
                 "menu_area": pv.get("menu_area"),
                 "row_count": pv.get("row_count", 0)}
                for pv in s.doc.values()]
    req.send_json({"ok": True, "identity": s.identity,
                   "meta": s.snapshot_meta, "read_keys": s.read_keys(),
                   "programs": programs})


def _resolve_prog_or_404(ctx, req, cat):
    prog = cat.program(req.params["key"])
    if prog is None:
        req.send_json({"ok": False,
                       "error": "unknown program %r" % req.params["key"]}, 404)
    return prog


def route_session_program(ctx, req):
    """GET /api/sessions/{id}/program/{key} — one program's rows.

    From the working copy by default; ``?refresh=1`` does a live scoped read of
    just this program (read-only) and updates the working copy. An unread
    program returns its shaped empty view so the page says "no rows", never 404.
    """
    s = _session_or_404(ctx, req)
    if s is None:
        return
    try:
        cat = load_catalog()
    except Exception as exc:  # noqa: BLE001
        req.send_json({"ok": False, "error": f"catalog unavailable: {exc}"}, 500)
        return
    prog = _resolve_prog_or_404(ctx, req, cat)
    if prog is None:
        return
    if req.query.get("refresh") and s.client is not None:
        try:
            view, error = list_rows(s.client, cat, prog, width=10)
        except Exception as exc:  # noqa: BLE001 — SnmpError or transport
            req.send_json({"ok": False, "error": str(exc)})
            return
        s.put_program_view(view)
        req.send_json({"ok": True, "program": view, "source": "live",
                       "error": error})
        return
    view = s.program_view(prog.key)
    if view is None:
        req.send_json({"ok": True, "program": empty_program_view(cat, prog.key),
                       "source": "unread"})
        return
    req.send_json({"ok": True, "program": view, "source": "snapshot"})


def route_session_program_row(ctx, req):
    """GET /api/sessions/{id}/program/{key}/{index} — one row (record pane).

    From the working copy by default; ``?refresh=1`` does a targeted live GET of
    just that instance (the record pane's ⟳ re-read)."""
    s = _session_or_404(ctx, req)
    if s is None:
        return
    try:
        cat = load_catalog()
    except Exception as exc:  # noqa: BLE001
        req.send_json({"ok": False, "error": f"catalog unavailable: {exc}"}, 500)
        return
    prog = _resolve_prog_or_404(ctx, req, cat)
    if prog is None:
        return
    index = req.params["index"]
    if req.query.get("refresh") and s.client is not None:
        try:
            row, error = get_row(s.client, cat, prog, index)
        except Exception as exc:  # noqa: BLE001 — SnmpError or transport
            req.send_json({"ok": False, "error": str(exc)})
            return
        req.send_json({"ok": row is not None, "row": row, "source": "live",
                       "error": error})
        return
    view = s.program_view(prog.key)
    row = None
    if view is not None:
        row = next((r for r in view["rows"] if r["index"] == index), None)
    req.send_json({"ok": row is not None, "row": row, "source": "snapshot"})


# --------------------------------------------------------------------------
# value index: palette value search + where-used, over the working copy
# --------------------------------------------------------------------------
def route_session_find(ctx, req):
    """GET /api/sessions/{id}/find?q=… — value search over the working copy.

    Resolves the palette query grammar (improvements.md §2.1): a DN, name, digit
    string, or ``prg:``/``field:``/``cos:``/``dn:``/``vm:`` prefix → every
    program/row/field that holds it, grouped by program. The where-used chips
    are this search with a fixed query (``?refs=1`` restricts to reference
    fields)."""
    s = _session_or_404(ctx, req)
    if s is None:
        return
    q = req.query.get("q") or ""
    if not q:
        req.send_json({"ok": True, "query": "", "count": 0, "groups": []})
        return
    idx = build_index_from_views({"programs": list(s.doc.values())})
    if req.query.get("refs"):
        occ = idx.references_to(q, kind=req.query.get("kind"))
        req.send_json({"ok": True, "query": q, "count": len(occ),
                       "occurrences": occ})
        return
    res = search(idx, q, limit=int(req.query.get("limit") or 200))
    req.send_json({"ok": True, **res})


def route_snapshot_find(ctx, req):
    """GET /api/sites/{id}/snapshots/{sid}/find?q=… — value search in file mode."""
    doc = ctx.snapshots().get(req.params["id"], req.params["sid"])
    if doc is None:
        req.send_json({"ok": False, "error": "no such snapshot"}, 404)
        return
    q = req.query.get("q") or ""
    idx = build_index(doc, load_catalog())
    if req.query.get("refs"):
        occ = idx.references_to(q, kind=req.query.get("kind"))
        req.send_json({"ok": True, "query": q, "count": len(occ),
                       "occurrences": occ})
        return
    res = search(idx, q, limit=int(req.query.get("limit") or 200))
    req.send_json({"ok": True, **res})


# --------------------------------------------------------------------------
# cold start: snapshots on disk (browse with the device off)
# --------------------------------------------------------------------------
def _snapshot_header(entry: dict) -> dict:
    """A store index entry mapped to the UI's timeline/header shape.

    The store speaks the v2 names (``id``, ``read_at``, ``name``); the UI's
    cold-start code reads ``sid`` / ``saved_at`` / ``label``. Both are provided
    so neither side has to change, plus the v2 timeline fields."""
    ident = entry.get("identity") or {}
    return {
        "sid": entry.get("id"), "id": entry.get("id"),
        "saved_at": entry.get("read_at"), "read_at": entry.get("read_at"),
        "label": entry.get("name"), "name": entry.get("name"),
        "kind": entry.get("kind"), "pinned": bool(entry.get("pinned")),
        "tags": entry.get("tags") or [], "note": entry.get("note"),
        "scope": entry.get("scope"), "counts": entry.get("counts") or {},
        "swid": entry.get("swid"),
        "identity": {"swid": entry.get("swid"), **ident},
        "content_hash": entry.get("content_hash"),
        "dedupe_of": entry.get("dedupe_of"), "bytes": entry.get("bytes"),
        "redacted": bool(entry.get("redacted")),
    }


def _full_snapshot(doc: dict, cat) -> dict:
    """A stored backup doc mapped to the UI's full-snapshot shape (with
    rendered ``program_views`` so file-mode uses the live program pages)."""
    meta = doc.get("meta", {})
    snap = meta.get("snapshot", {})
    return {
        "sid": snap.get("id"), "site_id": meta.get("site"),
        "saved_at": meta.get("read_at"), "label": snap.get("name"),
        "pinned": bool(snap.get("pinned")), "kind": snap.get("kind"),
        "identity": {"swid": meta.get("swid"),
                     "chassis_mac": meta.get("chassis_mac")},
        "meta": meta,
        "program_views": program_views_from_backup(doc, cat),
    }


def route_site_snapshots(ctx, req):
    """GET /api/sites/{id}/snapshots — timeline entries, newest first.

    ``?kind=`` / ``?tag=`` narrow it (the timeline filter)."""
    entries = ctx.snapshots().index(req.params["id"],
                                    kind=req.query.get("kind"),
                                    tag=req.query.get("tag"))
    req.send_json({"ok": True,
                   "snapshots": [_snapshot_header(e) for e in entries]})


def route_site_snapshot_latest(ctx, req):
    """GET /api/sites/{id}/snapshots/latest — the full last snapshot (cold start)."""
    doc = ctx.snapshots().latest(req.params["id"])
    if doc is None:
        req.send_json({"ok": False, "snapshot": None})
        return
    req.send_json({"ok": True, "snapshot": _full_snapshot(doc, load_catalog())})


def route_site_snapshot_get(ctx, req):
    """GET /api/sites/{id}/snapshots/{sid} — one full saved snapshot (file mode)."""
    doc = ctx.snapshots().get(req.params["id"], req.params["sid"])
    if doc is None:
        req.send_json({"ok": False, "snapshot": None}, 404)
        return
    req.send_json({"ok": True, "snapshot": _full_snapshot(doc, load_catalog())})


# --------------------------------------------------------------------------
# Backups page: take / rename / delete / export / import / program / diff
# --------------------------------------------------------------------------
def _reader_for(ctx, params):
    """A live (read-only) SNMP client from a connected session or adhoc params.

    ``{"session": id}`` reuses the client the snapshot-on-connect attached (no
    reconnect); otherwise ``{"ip", "community", ...}`` opens a fresh read."""
    sid = params.get("session")
    if sid:
        s = ctx.sessions.get(sid)
        if s is not None and s.client is not None:
            return s.client, (s.transport or "direct")
    reader = _reader(params, keep_raw_walk=False)
    transport = "overlay" if params.get("reach") == "remote" else "direct"
    return reader.client, transport


def route_site_snapshot_take(ctx, req):
    """POST /api/sites/{id}/snapshots — take a snapshot now (read-only).

    ``{scope: all|core, name?, tags?, session?|ip?}``; stores a v2 .cixbak and
    prunes. This is the Backups page *New snapshot* button."""
    site_id = req.params["id"]
    params = req.body() or {}
    try:
        cat = load_catalog()
        client, transport = _reader_for(ctx, params)
    except ValueError as exc:
        req.send_json({"ok": False, "error": str(exc)}, 400)
        return
    scope = params.get("scope", "all")
    programs = None
    if scope == "core":
        programs = core_program_keys(cat)
    try:
        store = ctx.snapshots()
        entry = store.take(client, site_id=site_id, catalog=cat, scope=scope,
                           programs=programs, site=params.get("site"),
                           name=params.get("name"), tags=params.get("tags"),
                           kind="named" if params.get("name") else "manual",
                           transport=transport)
        store.prune(site_id)
    except SnmpError as exc:
        req.send_json({"ok": False, "error": str(exc)})
        return
    req.send_json({"ok": True, "snapshot": _snapshot_header(entry)})


def route_site_snapshot_patch(ctx, req):
    """PATCH /api/sites/{id}/snapshots/{sid} — name / note / tags / pin."""
    body = req.body() or {}
    kw = {}
    if "name" in body:
        entry = ctx.snapshots().name(req.params["id"], req.params["sid"], body["name"])
    else:
        if "note" in body:
            kw["note"] = body["note"]
        if "tags" in body:
            kw["tags"] = body["tags"]
        if "pinned" in body:
            kw["pinned"] = bool(body["pinned"])
        entry = ctx.snapshots().set_meta(req.params["id"], req.params["sid"], **kw)
    if entry is None:
        req.send_json({"ok": False, "error": "no such snapshot"}, 404)
        return
    req.send_json({"ok": True, "snapshot": _snapshot_header(entry)})


def route_site_snapshot_delete(ctx, req):
    """DELETE /api/sites/{id}/snapshots/{sid} — refuses a protected one unless
    ``?force=1`` (pinned / named / newest-full / referenced)."""
    ok, reason = ctx.snapshots().delete(req.params["id"], req.params["sid"],
                                        force=bool(req.query.get("force")))
    req.send_json({"ok": ok, "reason": reason}, 200 if ok else 409)


def route_site_snapshot_export(ctx, req):
    """GET /api/sites/{id}/snapshots/{sid}/export?redact=1&container=cixbak."""
    redact = req.query.get("redact", "1") not in ("0", "false", "no")
    container = req.query.get("container", "cixbak")
    out = ctx.snapshots().export(req.params["id"], req.params["sid"],
                                 redact_secrets=redact, container=container)
    if out is None:
        req.send_json({"ok": False, "error": "no such snapshot"}, 404)
        return
    filename, data = out
    ctype = "application/zip" if container == "cixbak" else "application/json"
    req.send_bytes(data, ctype, filename=filename)


def route_site_snapshot_import(ctx, req):
    """POST /api/sites/{id}/snapshots/import — {doc} → an imported snapshot."""
    body = req.body() or {}
    doc = body.get("doc")
    if not isinstance(doc, dict):
        req.send_json({"ok": False, "error": "missing backup doc"}, 400)
        return
    try:
        entry = ctx.snapshots().import_doc(req.params["id"], doc,
                                           name=body.get("name"))
    except ValueError as exc:
        req.send_json({"ok": False, "error": str(exc)}, 400)
        return
    req.send_json({"ok": True, "snapshot": _snapshot_header(entry)})


def route_site_snapshot_program(ctx, req):
    """GET /api/sites/{id}/snapshots/{sid}/program/{key} — one program in file
    mode (so the viewer fetches per program, not the whole document)."""
    doc = ctx.snapshots().get(req.params["id"], req.params["sid"])
    if doc is None:
        req.send_json({"ok": False, "error": "no such snapshot"}, 404)
        return
    cat = load_catalog()
    prog = cat.program(req.params["key"])
    if prog is None:
        req.send_json({"ok": False, "error": "unknown program"}, 404)
        return
    views = program_views_from_backup(doc, cat)
    pv = next((p for p in views["programs"] if p["catalog_key"] == prog.key), None)
    if pv is None:
        pv = empty_program_view(cat, prog.key)
        req.send_json({"ok": True, "program": pv, "source": "absent"})
        return
    req.send_json({"ok": True, "program": pv, "source": "file"})


# -- diff / compare-with-live ----------------------------------------------
def _resolve_backup_source(ctx, spec):
    """A backup doc from a diff source spec: ``{doc}`` | ``{site, snapshot}`` |
    ``{site, latest: true}``."""
    if not isinstance(spec, dict):
        return None
    if isinstance(spec.get("doc"), dict):
        return spec["doc"]
    site = spec.get("site")
    if site and spec.get("snapshot"):
        return ctx.snapshots().get(site, spec["snapshot"])
    if site and spec.get("latest"):
        return ctx.snapshots().latest(site)
    return None


def _annotated_diff(ctx, a_doc, b_doc, params, *, site_for_blame=None):
    cat = load_catalog()
    kw = {"catalog": cat, "ignore_readonly": not params.get("all")}
    if not params.get("volatile"):
        kw["volatile"] = load_volatile_oids()
    if params.get("cross_site"):
        ident = set((a_doc.get("meta", {}).get("identity_programs") or [])) | \
            set((b_doc.get("meta", {}).get("identity_programs") or []))
        kw["exclude_programs"] = ident
        kw["exclude_fields"] = CROSS_SITE_EXCLUDE_FIELDS
        kw["match_rows_on"] = "key"
    d = diff_backups(a_doc, b_doc, **kw)
    ann = annotate(d, cat)
    if site_for_blame:
        attribute(ann, ctx.snapshots().read_activity(site_for_blame))
    return d, ann, cat


def route_annotated_diff(ctx, req):
    """POST /api/diff/review — annotated diff between two states (backups.md §4).

    The Backups-page diff pane / the P2 review dialog. ``{a, b, all?, volatile?,
    cross_site?, export?}``; ``a``/``b`` are source specs (``{doc}`` | ``{site,
    snapshot}`` | ``{site, latest}``). With ``export`` ∈ ``markdown|csv|text|
    json`` returns that masked rendering. (The legacy ``/api/diff`` — full docs
    in, ``{diff, report}`` out — is kept for the old UI.)"""
    params = req.body() or {}
    a_doc = _resolve_backup_source(ctx, params.get("a"))
    b_doc = _resolve_backup_source(ctx, params.get("b"))
    if a_doc is None or b_doc is None:
        req.send_json({"ok": False, "error": "need two resolvable sources (a, b)"}, 400)
        return
    site = (params.get("a") or {}).get("site") or (params.get("b") or {}).get("site")
    d, ann, cat = _annotated_diff(ctx, a_doc, b_doc, params, site_for_blame=site)
    export = params.get("export")
    if export:
        if export == "markdown":
            req.send_text(to_markdown(d, cat), content_type="text/markdown; charset=utf-8")
        elif export == "csv":
            req.send_text(to_csv(d, cat), content_type="text/csv; charset=utf-8")
        elif export == "json":
            req.send_json(to_json(d, cat))
        else:
            req.send_text(to_text(d, cat))
        return
    req.send_json({"ok": True, "summary": d["summary"], "annotated": ann})


def route_site_compare_live(ctx, req):
    """POST /api/sites/{id}/compare-live — diff a snapshot against a fresh live
    read scoped to its programs (backups.md §4.1). Needs a connected session
    (``session``) or adhoc connection params; stores the read as ``compare-live``."""
    site_id = req.params["id"]
    params = req.body() or {}
    a_doc = ctx.snapshots().get(site_id, params.get("snapshot")) \
        if params.get("snapshot") else ctx.snapshots().latest(site_id)
    if a_doc is None:
        req.send_json({"ok": False, "error": "no snapshot to compare"}, 404)
        return
    try:
        cat = load_catalog()
        client, transport = _reader_for(ctx, params)
    except ValueError as exc:
        req.send_json({"ok": False, "error": str(exc)}, 400)
        return
    programs = list((a_doc.get("programs") or {}).keys())
    try:
        store = ctx.snapshots()
        b_entry = store.take(client, site_id=site_id, catalog=cat, scope=programs,
                             programs=programs, kind="compare-live",
                             transport=transport, trigger="compare-live")
    except SnmpError as exc:
        req.send_json({"ok": False, "error": str(exc)})
        return
    b_doc = store.get(site_id, b_entry["id"])
    d, ann, _ = _annotated_diff(ctx, a_doc, b_doc, params, site_for_blame=site_id)
    req.send_json({"ok": True, "summary": d["summary"], "annotated": ann,
                   "b_snapshot": _snapshot_header(b_entry)})


# A small set of per-row identity fields excluded on a cross-site diff
# (backups.md §4.4) — a station's own name / equipment number / MAC differ
# between systems by definition and are not "drift".
CROSS_SITE_EXCLUDE_FIELDS = {
    "stationStationName", "ipStationStationName", "stationEquipmentNumber",
    "stationMacAddress", "ipStationMacAddress", "stationIpAddress",
}


# --------------------------------------------------------------------------
# wiring
# --------------------------------------------------------------------------
# --------------------------------------------------------------------------
# Voice Mail routes (DESIGN_PLAN §8.2, voicemail-map §7) — read-only in P1
# --------------------------------------------------------------------------
def _vm(ctx) -> VmSession:
    """The one exclusive VM session, created lazily and stashed on the ctx."""
    mgr = getattr(ctx, "_vm_manager", None)
    if mgr is None:
        mgr = VmSessionManager()
        ctx._vm_manager = mgr
    return mgr.session


def _vm_guard(ctx, req, fn):
    """Run ``fn(vm)`` translating a not-connected session into a clean 409."""
    try:
        return fn(_vm(ctx))
    except VmNotConnected as exc:
        req.send_json({"ok": False, "error": str(exc)}, 409)
        return None


def route_vm_ports(ctx, req):
    req.send_json({"ok": True, "ports": vm_serial.discover_ports()})


def route_vm_connect(ctx, req):
    spec = req.body() or {}
    try:
        status = _vm(ctx).connect(spec)
    except Exception as exc:  # noqa: BLE001 — surface the exe-style error text
        req.send_json({"ok": False, "error": str(exc)}, 400)
        return
    req.send_json({"ok": True, "status": status})


def route_vm_disconnect(ctx, req):
    _vm(ctx).disconnect()
    req.send_json({"ok": True})


def route_vm_status(ctx, req):
    req.send_json({"ok": True, "status": _vm(ctx).status()})


def route_vm_boxes(ctx, req):
    refresh = bool(req.query.get("refresh"))
    res = _vm_guard(ctx, req, lambda vm: vm.boxes(refresh=refresh))
    if res is not None:
        req.send_json({"ok": True, "boxes": res})


def route_vm_box(ctx, req):
    box = req.params["id"]
    refresh = bool(req.query.get("refresh"))
    res = _vm_guard(ctx, req, lambda vm: vm.box(box, refresh=refresh))
    if res is not None:
        req.send_json({"ok": True, **res})


